'use client';
 
import { useState, useMemo } from 'react';
import { useRouter, Link } from '@/i18n/navigation';
import { useTranslations } from 'next-intl';
import { DataTable } from '@/components/shared/DataTable/DataTable';
import { ColumnDef } from '@tanstack/react-table';
import { useAdjustmentList, AdjustmentSummary } from '@/features/operations/hooks/useAdjustmentList';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { MetricCard } from '@/components/ui/metric-card';
import { EmptyState } from '@/components/shared/EmptyState';
import { Button } from '@/components/ui/button';
import { Plus, CheckCircle2, Clock, Activity, FileCheck, AlertTriangle, Filter } from 'lucide-react';
import { StatusBadge } from '@/components/shared/StatusBadge';
import { format } from 'date-fns';
import { PageHeader } from '@/components/shared/PageHeader';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Input } from '@/components/ui/input';
import { isAdjustmentPending, isAdjustmentPosted } from '@/domain/status-guards';
import { ADJUSTMENT_STATUS_UI } from '@/domain/status-ui-map';
import { ADJUSTMENT_STATUS } from '@/contracts/statuses';
 
// Reason ظْ Semantic visual styling (Hardened for Culinary Architect)
const REASON_CHIP: Record<string, string> = {
 DAMAGE: 'bg-status-error/10 text-status-error font-bold border border-status-error/5',
 EXPIRY: 'bg-status-warning/10 text-status-warning font-bold border border-status-warning/5',
 THEFT: 'bg-status-error/10 text-status-error font-bold border border-status-error/5',
 COUNTING_ERROR:'bg-status-secondary/10 text-status-secondary font-bold border border-status-secondary/5',
 OTHER: 'bg-surface-container-highest/30 text-muted-foreground font-bold border border-outline-low/5',
};
 
 
export function AdjustmentListClient() {
 const t = useTranslations('operations.adjustment');
 const tCommon = useTranslations('common');
 const router = useRouter();
 
 const [page, setPage] = useState(1);
 const [status, setStatus] = useState<string>('');
 
 const { data, isLoading } = useAdjustmentList({ status, page });
 
 const columns = useMemo<ColumnDef<AdjustmentSummary>[]>(() => [
 {
 accessorKey: 'status',
 header: tCommon('status_label'),
 cell: ({ row }) => (
 <StatusBadge status={row.original.status} />
 ),
 },
 {
 accessorKey: 'document_number',
 header: t('doc_number'),
 cell: ({ row }) => (
 <span dir="ltr" className="font-mono text-status-active text-body-md font-semibold">
 {row.original.document_number}
 </span>
 ),
 },
 {
 accessorKey: 'reason',
 header: t('reason'),
 cell: ({ row }) => {
 const reason = row.original.reason.toLowerCase();
 const cls = REASON_CHIP[row.original.reason as keyof typeof REASON_CHIP] ?? REASON_CHIP.OTHER;
 const label = t.has(`reasons.${reason}`) ? t(`reasons.${reason}`) : row.original.reason;
 return (
 <span className={`inline-flex items-center px-2.5 py-1 rounded-md text-label-xxs uppercase ${cls}`}>
 {label}
 </span>
 );
 },
 },
 {
 accessorKey: 'warehouse_id',
 header: tCommon('warehouse'),
 cell: ({ row }) => <span className="opacity-80 font-medium">{tCommon('warehouses.' + row.original.warehouse_id.toLowerCase())}</span>,
 },
 {
 accessorKey: 'approved_by',
 header: t('approved_by'),
 cell: ({ row }) =>
 row.original.approved_by ? (
 <span className="inline-flex items-center gap-1.5 text-label-xs font-bold text-status-success">
 <CheckCircle2 className="w-3.5 h-3.5" />
 {row.original.approved_by}
 </span>
 ) : (
 <span className="inline-flex items-center gap-1.5 text-label-xs font-bold text-muted-foreground/30 italic">
 <Clock className="w-3.5 h-3.5" />
 {tCommon('status.pending') || 'Pending'}
 </span>
 ),
 },
 {
 accessorKey: 'created_at',
 header: tCommon('created_at'),
 cell: ({ row }) =>
 row.original.created_at ? (
 <span dir="ltr" className="text-label-xs text-muted-foreground/40 font-mono font-medium">
 {format(new Date(row.original.created_at), 'dd/MM/yyyy')}
 </span>
 ) : <span className="opacity-20 text-label-xs">ظ¤</span>,
 },
 {
 id: 'actions',
 header: '',
 cell: ({ row }) => (
 <div className="flex justify-end">
 <Button 
 variant="ghost" 
 size="sm" 
 className="text-label-xs font-bold uppercase text-status-active hover:bg-status-active/10 h-8 px-4 rounded-md"
 onClick={(e) => {
 e.stopPropagation();
 router.push(`/adjustments/${row.original.id}`);
 }}
 >
 {tCommon('view')}
 </Button>
 </div>
 ),
 },
 ], [t, tCommon, router]);
 
  const totalAdjustments = data?.meta?.total || 0;
  const inProgressCount = data?.data?.filter(i => isAdjustmentPending(i.status)).length || 0;
  const postedCount = data?.data?.filter(i => isAdjustmentPosted(i.status)).length || 0;
  const majorAdjustmentsCount = data?.data?.filter(a => a.reason === 'DAMAGE' || a.reason === 'THEFT').length || 0;
  const pendingApprovalsCount = inProgressCount;
 
 return (
 <div className="p-8 max-w-[1600px] mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-1000">
 <Breadcrumb 
 items={[
 { label: tCommon('inventory'), href: '#' },
 { label: t('title'), href: '/adjustments' }
 ]} 
 />
 <PageHeader 
 title={t('title')} 
 description={t('description') || 'Corrective inventory volume adjustments and audits'} actions={
 <div className="flex items-center gap-6">
 <div className="flex flex-col items-end gap-1 border-e border-outline-low pe-6 hidden md:flex">
 <div className="text-label-xs font-semibold uppercase text-muted-foreground/60 flex items-center gap-2">
 <span className="w-1.5 h-1.5 rounded-full bg-cyan-500 animate-pulse shadow-[0_0_8px_rgba(0,229,255,0.8)]" />
 {tCommon('status.live_updates') || 'Correction Pulse'}
 </div>
 <div dir="ltr" className="text-label-xxs font-bold text-muted-foreground/40">
 {tCommon('status.last_sync') || 'Last Sync'}: {new Date().toLocaleTimeString()}
 </div>
 </div>
 <PermissionGate action="create" resource="adjustment">
 <Link href="/adjustments/new">
 <Button className="h-10 px-8 bg-surface-container-low border border-outline-low/10 text-status-active text-label-xs font-bold uppercase rounded-md transition-all hover:bg-surface-container-medium shadow-sm gap-2">
 <Plus className="w-3.5 h-3.5" />
 {t('create_new')}
 </Button>
 </Link>
 </PermissionGate>
 </div>
 }
 />
 
 {/* Summary Cards - Operational Nocturne Standard */}
 <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
 <MetricCard
 label={t('correction_volume')}
 value={totalAdjustments}
 icon={Activity}
 trend="active"
 />
 <MetricCard
 label={t('pending_approval')}
 value={pendingApprovalsCount}
 icon={FileCheck}
 trend="active"
 color="amber"
 />
 <MetricCard
 label={t('critical_losses')}
 value={majorAdjustmentsCount}
 icon={AlertTriangle}
 trend="active"
 color="rose"
 />
 </div>
 
 <DataTable 
 columns={columns}
 data={data?.data || []}
 isLoading={isLoading}
 onRowClick={(row: AdjustmentSummary) => router.push(`/adjustments/${row.id}`)}
 collectionName="operations_adjustments"
 emptyState={
 <EmptyState 
 title={t('no_records') || 'No Adjustments Found'} description={t('description') || 'Register your first inventory adjustment to recalibrate stock levels.'} action={
 <PermissionGate action="create" resource="adjustment">
 <Button 
 onClick={() => router.push('/adjustments/new')}
 className="bg-cyan-500/10 hover:bg-cyan-500/20 text-cyan-500 border border-cyan-500/20"
 >
 <Plus className="w-4 h-4 me-2" />
 {t('create_new')}
 </Button>
 </PermissionGate>
 }
 />
 }
 pagination={data?.meta ? {
 page: page,
 pageSize: 10,
 total: data.meta.total,
 totalPages: data.meta.total_pages,
 onPageChange: setPage
 } : undefined}
 filters={
 <div className="flex flex-wrap items-center gap-6 w-full py-6 px-8 bg-surface-container-low border border-outline-low/5 rounded-lg">
 <div className="flex flex-col gap-2.5 min-w-[240px] flex-1">
 <label className="text-label-xs font-bold uppercase text-muted-foreground/40 ms-1">{tCommon('status_label')}</label>
 <Select
 value={status || 'ALL'} onValueChange={(val: string | null) => { 
 const nextStatus = val === 'ALL' || !val ? '' : val;
 setStatus(nextStatus); 
 setPage(1); 
 }}
 >
 <SelectTrigger className="w-full bg-surface-container-highest/20 border border-outline-low/10 h-12 px-5 text-label-xs font-bold uppercase rounded-md transition-all hover:bg-surface-container-highest/30 focus:ring-1 focus:ring-status-active/20">
 <SelectValue placeholder={tCommon('status.all')} />
 </SelectTrigger>
              <SelectContent className="bg-surface-container-high border-outline-low/10 rounded-xl shadow-2xl">
                <SelectItem value="ALL" className="text-label-xs font-bold uppercase">{tCommon('status.all')}</SelectItem>
                {Object.entries(ADJUSTMENT_STATUS_UI).filter(([key]) => Object.values(ADJUSTMENT_STATUS).includes(key as any)).map(([key, config]) => (
                  <SelectItem key={key} value={key} className="text-label-xs font-bold uppercase">
                    {tCommon(config.labelKey)}
                  </SelectItem>
                ))}
              </SelectContent>
 </Select>
 </div>
 
 <div className="flex flex-col gap-2.5 min-w-[300px] flex-[2]">
 <label className="text-label-xs font-bold uppercase text-muted-foreground/40 ms-1">{tCommon('search')}</label>
 <div className="relative group">
 <Input
 placeholder={t('search_placeholder') || 'Search Adjustment Documents...'} className="w-full bg-surface-container-highest/20 border border-outline-low/10 h-12 ps-12 pe-4 text-label-xs font-bold rounded-md transition-all group-hover:bg-surface-container-highest/30 focus:ring-1 focus:ring-status-active/20 placeholder:text-muted-foreground/20"
 />
 <svg className="absolute start-4 top-1/2 -translate-y-1/2 w-4 h-4 text-status-active/40 transition-colors group-hover:text-status-active/60" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
 </div>
 </div>
 
 <Button className="h-12 px-8 bg-surface-container-highest/30 hover:bg-surface-container-highest/50 text-foreground text-label-xs font-bold uppercase rounded-md transition-all border border-outline-low/10 group">
 <Filter className="w-3.5 h-3.5 me-2 transition-transform group-hover:rotate-180 text-status-active/60" />
 {tCommon('filters_button')}
 </Button>
 </div>
 }
 />
 </div>
 );
}

'use client';

import { useTranslations } from 'next-intl';
import { useAdjustment } from '@/features/operations/hooks/useAdjustment';
import { useAuth } from '@/providers/AuthProvider';
import { ConflictDialog } from '@/core/concurrency/ConflictDialog';
import { useConflictHandler } from '@/core/concurrency/useConflictHandler';
import { ADJUSTMENT_STATUS } from '@/contracts/statuses';
import { isLocked } from '@/domain/status-guards';
import { AdjustmentForm } from './AdjustmentForm';

import { PageSkeleton } from '@/components/shared/PageSkeleton';

export function AdjustmentDetailClient({ id }: { id: string }) {
  const tCommon = useTranslations('common');
  const { user } = useAuth();
  const conflict = useConflictHandler('adjustment', id);
  
  const isNew = id === 'new';
  const { data: adjustment, isLoading } = useAdjustment(isNew ? null : id);

  if (isLoading) return <PageSkeleton variant="detail" />;

  const status = adjustment?.status ?? ADJUSTMENT_STATUS.DRAFT;
  const locked = isLocked('ADJUSTMENT', status);



  return (
    <>
      <AdjustmentForm 
        document={adjustment}
        id={id}
        isLocked={locked}
        onConflict={conflict.triggerConflict}
      />
      <ConflictDialog 
        open={conflict.open} 
        onClose={conflict.handleClose} 
        onReload={conflict.handleReload} 
      />
    </>
  );
}

'use client';

import { useState, useEffect, useMemo } from 'react';
import { toast } from 'sonner';

import { useTranslations, useLocale } from 'next-intl';
import { useRouter } from '@/i18n/navigation';
import { Button } from '@/components/ui/button';
import { DocumentReadOnlyOverlay } from '@/components/shared/DocumentReadOnlyOverlay';
import { PostConfirmDialog } from '@/components/shared/PostConfirmDialog';
import { useCreateAdjustment } from '@/features/operations/hooks/useCreateAdjustment';
import { useApproveAdjustment } from '@/features/operations/hooks/useApproveAdjustment';
import { usePostAdjustment } from '@/features/operations/hooks/usePostAdjustment';
import { useSubmitAdjustment } from '@/features/operations/hooks/useSubmitAdjustment';
import { useRejectAdjustment } from '@/features/operations/hooks/useRejectAdjustment';
import { useUpdateAdjustment } from '@/features/operations/hooks/useUpdateAdjustment';
import { useAuth } from '@/providers/AuthProvider';
import { useWarehouseLock } from '@/hooks/useWarehouseLock';
import { StatusTimeline, type Status } from '@/components/shared/StatusTimeline';
import { format } from 'date-fns';
import { 
  ArrowUp, 
  ArrowDown, 
  ArrowLeft,
  CheckCircle, 
  Trash2, 
  Package, 
  Send,
  XCircle, 
  History,
  Info,
  Clock,
  AlertCircle
} from 'lucide-react';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { ScanInput } from '@/components/shared/ScanInput/ScanInput';
import { z } from 'zod';
import { apiClient } from '@/lib/api/client';
import { cn } from '@/lib/utils';
import { 
  Dialog, 
  DialogContent, 
  DialogHeader, 
  DialogTitle, 
  DialogDescription,
  DialogFooter
} from "@/components/ui/dialog";
import { StatusBadge, type BadgeStatus } from '@/components/shared/StatusBadge';
import { ADJUSTMENT_STATUS, type DocumentStatus } from '@/contracts/statuses';
import { type AdjustmentLine, type AdjustmentDetail } from '@/features/operations/hooks/useAdjustment';
import { ActionGuard } from '@/core/workflow/ActionGuard';
import { DocumentLockBanner, DocumentLockWrapper } from '@/components/shared/DocumentLockBanner';
import { FormFooter } from '@/components/shared/FormFooter';

const REASON_OPTIONS = ['DAMAGE', 'EXPIRY', 'THEFT', 'COUNTING_ERROR', 'CORRECTION', 'OTHER'] as const;

interface AdjustmentFormProps {
  document?: AdjustmentDetail;
  id: string;
  isLocked: boolean;
  onConflict?: () => void;
}

export function AdjustmentForm({ 
  document, 
  id, 
  isLocked,
  onConflict
}: AdjustmentFormProps) {
  const t = useTranslations('operations.adjustment');
  const tc = useTranslations('common');
  const locale = useLocale();
  const router = useRouter();
  const { user } = useAuth();
  
  const isNew = id === 'new';
  const adjustmentStatus = (document?.status as DocumentStatus) ?? ADJUSTMENT_STATUS.DRAFT;

  const createAdjustment = useCreateAdjustment();
  const submitAdjustment = useSubmitAdjustment(id, { onConflict });
  const approveAdjustment = useApproveAdjustment(id, { onConflict });
  const rejectAdjustment = useRejectAdjustment(id, { onConflict });
  const postAdjustment = usePostAdjustment({ onConflict });
  const updateAdjustment = useUpdateAdjustment({ onConflict });

  const [warehouseId, setWarehouseId] = useState(document?.warehouse_id || 'wh-1');
  const { data: lockState } = useWarehouseLock(warehouseId);
  const [reason, setReason] = useState<string>(document?.reason || 'DAMAGE');
  const [notes, setNotes] = useState(document?.notes || '');
  const [lines, setLines] = useState<AdjustmentLine[]>(document?.lines || []);
  
  const canEdit = !isLocked || isNew;
  
  // Dialog States
  const [submitDialogOpen, setSubmitDialogOpen] = useState(false);
  const [approveDialogOpen, setApproveDialogOpen] = useState(false);
  const [rejectDialogOpen, setRejectDialogOpen] = useState(false);
  const [scanStatus, setScanStatus] = useState<"idle" | "success" | "error">("idle");
  const [statusMessage, setStatusMessage] = useState<string | undefined>();
  const [postDialogOpen, setPostDialogOpen] = useState(false);
  const [rejectionComment, setRejectionComment] = useState('');

  // Sync state with adjustment data when it arrives or changes records
  const [prevAdjustmentId, setPrevAdjustmentId] = useState<string | null>(null);
  if (document && document.id !== prevAdjustmentId) {
    setPrevAdjustmentId(document.id);
    setWarehouseId(document.warehouse_id);
    setReason(document.reason);
    setNotes(document.notes ?? '');
    setLines(document.lines);
  }

  // Refresh stock levels when warehouse changes
  useEffect(() => {
    if (canEdit && lines.length > 0) {
      const refreshStock = async () => {
        const BalanceSchema = z.object({
          data: z.array(z.object({
            qty_on_hand: z.number()
          }))
        });
        
        const updatedLines = await Promise.all(lines.map(async (line) => {
          try {
            const balanceRes = await apiClient.get(
              `/inventory/balance?warehouse_id=${warehouseId}&search=${line.item.code}`, 
              BalanceSchema
            );
            const currentQty = balanceRes.data?.[0]?.qty_on_hand ?? 0;
            return { ...line, qty_before: currentQty };
          } catch {
            return line;
          }
        }));
        
        const hasChanged = updatedLines.some((l, i) => l.qty_before !== lines[i].qty_before);
        if (hasChanged) {
          setLines(updatedLines);
        }
      };
      
      refreshStock();
    }
  }, [warehouseId, canEdit]);

  const handleSaveDraft = async () => {
    if (lines.length === 0) return;
    try {
      const payload = {
        version: document?.version || 0,
        warehouse_id: warehouseId,
        reason,
        notes,
        lines: lines.map(l => ({
          id: l.id.startsWith('new-') ? undefined : l.id,
          item_id: l.item.id,
          qty: l.qty_adjusted,
          uom_id: l.uom_id,
          direction: l.direction
        }))
      };

      if (isNew) {
        await createAdjustment.mutateAsync(payload);
        toast.success(t('create_success'));
        router.push(`/${locale}/adjustments`);
      } else {
        await updateAdjustment.mutateAsync({ id, payload });
        toast.success(t('update_success'));
      }
    } catch (e) {
      console.error(e);
      toast.error(tc('error_occurred'));
    }
  };

  const handleSubmit = async () => {
    try {
      await submitAdjustment.mutateAsync(document?.version || 0);
      toast.success(t('submit_success'));
      setSubmitDialogOpen(false);
    } catch (e) {
      console.error(e);
      toast.error(tc('error_occurred'));
    }
  };

  const handleApprove = async () => {
    if (!!lockState?.isLocked) return;
    try {
      await approveAdjustment.mutateAsync(document?.version || 0);
      toast.success(t('approve_success'));
      setApproveDialogOpen(false);
    } catch (e) {
      console.error(e);
      toast.error(tc('error_occurred'));
    }
  };

  const handleReject = async () => {
    const trimmedComment = rejectionComment.trim();
    if (trimmedComment.length < 15) return;
    try {
      await rejectAdjustment.mutateAsync({ version: document?.version || 0, reject: trimmedComment });
      toast.success(t('reject_success'));
      setRejectDialogOpen(false);
    } catch (e) {
      console.error(e);
      toast.error(tc('error_occurred'));
    }
  };

  const handlePost = async () => {
    if (!!lockState?.isLocked) return;
    try {
      await postAdjustment.mutateAsync({ id, version: document?.version || 0 });
      setPostDialogOpen(false);
      router.push(`/${locale}/adjustments`);
    } catch (e) {
      console.error(e);
    }
  };

  const handleScan = async (barcode: string) => {
    if (!!lockState?.isLocked || !canEdit) return;
    
    const resetAfterDelay = () => {
      setTimeout(() => {
        setScanStatus("idle");
        setStatusMessage(undefined);
      }, 2000);
    };

    try {
      setScanStatus("idle");
      setStatusMessage(undefined);

      const ItemSchema = z.object({
        data: z.array(z.object({
          id: z.string(), code: z.string(), name_ar: z.string(), name_en: z.string(),
          primary_uom: z.object({ id: z.string(), code: z.string() })
        }))
      });
      const res = await apiClient.get(`/master-data/items?barcode=${barcode}`, ItemSchema);
      
      if (res.data && res.data.length > 0) {
        const item = res.data[0];
        
        const BalanceSchema = z.object({
          data: z.array(z.object({
            qty_on_hand: z.number()
          }))
        });
        const balanceRes = await apiClient.get(`/inventory/balance?warehouse_id=${warehouseId}&search=${item.code}`, BalanceSchema);
        const currentQty = balanceRes.data?.[0]?.qty_on_hand ?? 0;

        setLines(prev => {
          const existing = prev.find(l => l.item.id === item.id);
          if (existing) {
            return prev.map(l => l.item.id === item.id ? { ...l, qty_adjusted: l.qty_adjusted + 1, qty_before: currentQty } : l);
          }
          return [...prev, {
            id: `new-${Date.now()}`,
            item: {
              ...item,
              name_ar: item.name_ar,
              name_en: item.name_en,
              primary_uom: item.primary_uom
            },
            direction: 'INCREASE',
            qty_before: currentQty,
            qty_adjusted: 1,
            uom_id: item.primary_uom.id,
            reason_notes: ''
          }];
        });

        setScanStatus("success");
        setStatusMessage(undefined);
        resetAfterDelay();
      } else {
        setScanStatus("error");
        setStatusMessage(t('scan.not_found'));
        resetAfterDelay();
      }
    } catch {
      setScanStatus("error");
      setStatusMessage(tc('error'));
      resetAfterDelay();
    }
  };

  const removeLine = (id: string) => {
    if (!!lockState?.isLocked || !canEdit) return;
    setLines(prev => prev.filter(l => l.id !== id));
  };

  const updateLine = (id: string, updates: Partial<AdjustmentLine>) => {
    if (!!lockState?.isLocked || !canEdit) return;
    setLines(prev => prev.map(l => l.id === id ? { ...l, ...updates } : l));
  };

  const timelineEntries = useMemo(() => {
    if (!document?.timeline) return [];
    return document.timeline.map(e => ({
      status: e.status.toLowerCase() as Status,
      at: e.at,
      by: e.by
    }));
  }, [document]);
  return (
    <div className="min-h-screen bg-surface-container-low pb-12 animate-in fade-in duration-500">
      {/* Sticky Glass Header */}
      <div className="sticky top-0 z-50 w-full glass-header border-b border-outline-variant/50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex flex-col">
            <h1 className="font-semibold text-title-sm">
              {isNew ? t('create_new') : (document?.document_number || '...')}
            </h1>
            {!isNew && (
              <div className="flex items-center gap-2 mt-0.5">
                <StatusBadge status={adjustmentStatus as BadgeStatus} />
                <span className="text-label-xxs font-semibold uppercase text-muted-foreground/40 shrink-0">
                  {format(new Date(document?.created_at || new Date()), 'yyyy-MM-dd')}
                </span>
              </div>
            )}
          </div>
          
          {/* Workflow specific actions moved to FormFooter */}
        </div>
      </div>

      <form 
        onSubmit={(e) => e.preventDefault()} 
        className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-6 space-y-6"
      >
        <DocumentLockBanner 
          status={adjustmentStatus} 
          isLocked={isLocked} 
        />

        <DocumentLockWrapper isLocked={isLocked}>
          <div className="space-y-6">
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            {/* Left Column */}
            <div className="lg:col-span-8 space-y-8">
            <div className="bg-surface-container-lowest p-8 rounded-lg shadow-sm grid grid-cols-1 md:grid-cols-2 gap-8 border border-surface-variant/5">
              <div className="space-y-4">
                <div className="space-y-1.5">
                  <label className="text-label-xs font-semibold uppercase text-muted-foreground/40">{tc('warehouse')}</label>
                  <Select 
                    value={warehouseId} 
                    onValueChange={(val) => setWarehouseId(val || '')}
                    disabled={!canEdit || !!lockState?.isLocked}
                  >
                    <SelectTrigger className="bg-surface-container-low border-none h-12 rounded-lg font-bold text-body-md transition-all focus:ring-1 focus:ring-primary-fixed-dim/10">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent className="bg-surface-container-highest border-none rounded-lg shadow-2xl">
                      <SelectItem value="wh-1" className="font-bold text-body-md">Main Store</SelectItem>
                      <SelectItem value="wh-2" className="font-bold text-body-md">Kitchen Warehouse</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div className="space-y-1.5">
                  <label className="text-label-xs font-semibold uppercase text-muted-foreground/40">{t('reason')}</label>
                  <Select 
                    value={reason} 
                    onValueChange={(val) => setReason(val || '')}
                    disabled={!canEdit || !!lockState?.isLocked}
                  >
                    <SelectTrigger className="bg-surface-container-low border-none h-12 rounded-lg font-bold text-body-md transition-all focus:ring-1 focus:ring-primary-fixed-dim/10">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent className="bg-surface-container-highest border-none rounded-lg shadow-2xl">
                      {REASON_OPTIONS.map(opt => (
                        <SelectItem key={opt} value={opt} className="font-bold text-body-md">{t(`reason_${opt.toLowerCase()}`)}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-label-xs font-semibold uppercase text-muted-foreground/40">{tc('notes')}</label>
                <Textarea
                  value={notes}
                  onChange={e => setNotes(e.target.value)}
                  disabled={!canEdit || !!lockState?.isLocked}
                  placeholder={t('notes_placeholder')}
                  className="bg-surface-container-low border-none rounded-lg h-[calc(6rem+3rem+1rem)] p-4 text-body-md resize-none focus:ring-1 focus:ring-primary-fixed-dim/10 transition-all"
                />
              </div>
            </div>

            {/* Item Scanning / Adding */}
            {canEdit && adjustmentStatus !== ADJUSTMENT_STATUS.POSTED && (
              <div className="bg-surface-container-lowest p-8 rounded-lg shadow-sm space-y-6 border border-surface-variant/5">
                <div className="flex items-center gap-3">
                  <Package className="w-5 h-5 text-primary" />
                  <h3 className="text-label-sm font-semibold uppercase">{t('add_item')}</h3>
                </div>
                <ScanInput 
                  onScan={handleScan}
                  placeholder={t('scan_placeholder')}
                  disabled={!!lockState?.isLocked}
                  scanStatus={scanStatus}
                  statusMessage={statusMessage}
                />
              </div>
            )}

            {/* Items Table */}
            <div className="bg-surface-container-lowest rounded-lg shadow-sm overflow-hidden border border-surface-variant/5">
              <div className="p-8 flex justify-between items-center">
                <div className="flex items-center gap-4">
                  <div className="w-1.5 h-6 bg-primary rounded-full" />
                  <h3 className="text-label-sm font-semibold uppercase">{tc('items')}</h3>
                </div>
              </div>
                <div className="overflow-x-auto">
                  <table className="w-full border-collapse">
                    <thead>
                      <tr className="bg-surface-container-low/50">
                        <th className="px-8 h-14 text-start text-label-xs font-semibold uppercase text-muted-foreground/60">{tc('item')}</th>
                        <th className="px-6 h-14 text-center text-label-xs font-semibold uppercase text-muted-foreground/60">{t('direction')}</th>
                        <th className="px-6 h-14 text-center text-label-xs font-semibold uppercase text-muted-foreground/60">{t('qty_before')}</th>
                        <th className="px-6 h-14 text-center text-label-xs font-semibold uppercase text-muted-foreground/60">{t('qty_adjusted')}</th>
                        <th className="px-6 h-14 text-center text-label-xs font-semibold uppercase text-muted-foreground/60">{t('qty_after')}</th>
                        {canEdit && <th className="px-8 h-14 text-end"></th>}
                      </tr>
                    </thead>
                    <tbody className="divide-y-0">
                      {lines.length === 0 && (
                        <tr>
                          <td colSpan={canEdit ? 6 : 5} className="px-8 py-20 text-center">
                            <div className="flex flex-col items-center gap-4 opacity-20">
                              <Package className="w-12 h-12" />
                              <p className="text-label-sm font-semibold uppercase">{tc('no_items')}</p>
                            </div>
                          </td>
                        </tr>
                      )}
                      {lines.map((line) => (
                        <tr key={line.id} className="group even:bg-surface-container-low/30 hover:bg-surface-container-high/20 transition-all border-none">
                          <td className="px-8 py-6">
                            <div className="flex flex-col min-w-0">
                              <span className="text-body-md font-bold truncate">{locale === 'ar' ? line.item.name_ar : line.item.name_en}</span>
                              <span className="text-label-xs font-mono text-primary/40 uppercase mt-1">{line.item.code}</span>
                            </div>
                          </td>
                          <td className="px-6 py-6 text-center">
                            <Select
                              value={line.direction}
                              onValueChange={(val) => updateLine(line.id, { direction: val as 'INCREASE' | 'DECREASE' })}
                              disabled={!canEdit}
                            >
                              <SelectTrigger className="bg-surface-container-low border-none h-10 w-32 mx-auto rounded-lg font-semibold text-label-xs uppercase focus:ring-1 focus:ring-primary-fixed-dim/10">
                                <SelectValue />
                              </SelectTrigger>
                              <SelectContent className="bg-surface-container-highest border-none rounded-lg shadow-2xl">
                                <SelectItem value="INCREASE" className="font-semibold text-label-xs uppercase text-emerald-500">{t('direction_increase')}</SelectItem>
                                <SelectItem value="DECREASE" className="font-semibold text-label-xs uppercase text-red-500">{t('direction_decrease')}</SelectItem>
                              </SelectContent>
                            </Select>
                          </td>
                          <td className="px-6 py-6 text-center tabular-nums">
                            <div className="flex flex-col items-center gap-0.5">
                              <span className="text-body-md font-bold text-muted-foreground/40">{line.qty_before.toFixed(3)}</span>
                              <span className="text-label-xxs font-semibold uppercase text-muted-foreground/30">{line.item.primary_uom.code}</span>
                            </div>
                          </td>
                          <td className="px-6 py-6 text-center tabular-nums">
                            <div className="flex flex-col items-center gap-0.5">
                              <input 
                                type="number"
                                value={line.qty_adjusted}
                                onChange={e => updateLine(line.id, { qty_adjusted: Number(e.target.value) })}
                                disabled={!canEdit}
                                className="bg-surface-container-low border-none h-10 w-24 text-center rounded-lg font-semibold text-body-md transition-all focus:ring-1 focus:ring-primary-fixed-dim/10"
                                step="0.001"
                                min="0"
                              />
                              <span className="text-label-xxs font-semibold uppercase text-muted-foreground/30">{line.item.primary_uom.code}</span>
                            </div>
                          </td>
                          <td className="px-6 py-6 text-center tabular-nums">
                            <div className="flex flex-col items-center gap-0.5">
                              <span className={cn(
                                "text-body-md font-bold",
                                (line.direction === 'INCREASE' ? line.qty_before + line.qty_adjusted : line.qty_before - line.qty_adjusted) < 0 ? "text-red-500" : "text-foreground"
                              )}>
                                {(line.direction === 'INCREASE' ? line.qty_before + line.qty_adjusted : line.qty_before - line.qty_adjusted).toFixed(3)}
                              </span>
                              <span className="text-label-xxs font-semibold uppercase text-muted-foreground/30">{line.item.primary_uom.code}</span>
                            </div>
                          </td>
                          {canEdit && (
                            <td className="px-8 py-6 text-end">
                              <Button 
                                variant="ghost" 
                                size="icon" 
                                onClick={() => removeLine(line.id)}
                                className="h-8 w-8 text-red-500/40 hover:text-red-500 hover:bg-red-500/10 rounded-lg transition-all"
                              >
                                <Trash2 className="w-4 h-4" />
                              </Button>
                            </td>
                          )}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
            </div>
          </div>

          {/* Right Column */}
          <div className="lg:col-span-4 space-y-8">
            <div className="bg-surface-container-lowest p-8 rounded-lg shadow-sm relative overflow-hidden group border border-surface-variant/5">
              <div className="absolute top-0 end-0 w-32 h-32 bg-primary/5 blur-[50px] -me-16 -mt-16 rounded-full group-hover:bg-primary/10 transition-all duration-700" />
              <div className="relative space-y-8">
                <div className="flex items-center gap-4">
                  <div className="w-10 h-10 rounded-lg bg-primary/10 flex items-center justify-center">
                    <History className="w-5 h-5 text-primary" />
                  </div>
                  <h4 className="text-label-xs font-semibold uppercase">{tc('audit_trail')}</h4>
                </div>
                {timelineEntries.length > 0 ? (
                  <div className="ps-2">
                    <StatusTimeline entries={timelineEntries} />
                  </div>
                ) : (
                  <div className="flex flex-col items-center justify-center py-8 opacity-20 gap-3">
                    <Clock className="w-10 h-10" />
                    <p className="text-label-xs font-semibold uppercase">{t('no_history')}</p>
                  </div>
                )}
              </div>
            </div>

            {!isNew && (
              <div className="bg-surface-container-lowest p-8 rounded-lg shadow-sm space-y-6 border border-surface-variant/5">
                <div className="flex items-center gap-4">
                  <div className="w-10 h-10 rounded-lg bg-emerald-500/10 flex items-center justify-center">
                    <Info className="w-5 h-5 text-emerald-500" />
                  </div>
                  <h4 className="text-label-xs font-semibold uppercase">{t('document_info')}</h4>
                </div>
                <div className="space-y-4">
                  <div className="flex justify-between items-center py-3 border-b border-surface-container-low">
                    <span className="text-label-sm text-muted-foreground">{tc('status')}</span>
                    <StatusBadge status={adjustmentStatus as BadgeStatus} />
                  </div>
                  {document?.posted_at && (
                    <div className="flex justify-between items-center py-3 border-b border-surface-container-low">
                      <span className="text-label-sm text-muted-foreground">{t('posted_at')}</span>
                      <span className="text-label-xs font-bold" dir="ltr">
                        {format(new Date(document.posted_at), 'yyyy-MM-dd HH:mm')}
                      </span>
                    </div>
                  )}
                  {document?.approved_by && (
                    <div className="flex justify-between items-center py-3 border-b border-surface-container-low">
                      <span className="text-label-sm text-muted-foreground">{t('approved_by')}</span>
                      <span className="text-label-xs font-semibold uppercase text-foreground/70">{document.approved_by}</span>
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>
            </div>
          </div>
        </DocumentLockWrapper>

        <FormFooter 
          onCancel={() => router.push(`/${locale}/adjustments`)}
          onSubmit={handleSaveDraft}
          isSaving={createAdjustment.isPending || updateAdjustment.isPending}
          isLocked={isLocked}
          isDirty={lines.length > 0}
          isValid={lines.length > 0 && notes.trim().length >= 10}
          actions={
            !isNew && (
              <div className="flex items-center gap-3">
                <ActionGuard documentType="ADJUSTMENT" status={adjustmentStatus} action="SUBMIT" role={user?.role || 'WH_KEEPER'}>
                  <Button 
                    variant="outline"
                    onClick={() => setSubmitDialogOpen(true)}
                    className="h-14 px-8 border-primary/20 text-primary hover:bg-primary/5 text-label-xs font-black uppercase tracking-widest rounded-2xl transition-all"
                  >
                    <Send className="w-5 h-5 me-3" />
                    {t('submit_for_approval')}
                  </Button>
                </ActionGuard>

                <ActionGuard documentType="ADJUSTMENT" status={adjustmentStatus} action="REJECT" role={user?.role || 'WH_KEEPER'}>
                  <Button 
                    variant="ghost" 
                    onClick={() => setRejectDialogOpen(true)}
                    className="h-14 px-8 text-red-500 hover:bg-red-500/5 text-label-xs font-black uppercase tracking-widest rounded-2xl transition-all"
                  >
                    <XCircle className="w-5 h-5 me-3" />
                    {t('reject')}
                  </Button>
                </ActionGuard>
                
                <ActionGuard documentType="ADJUSTMENT" status={adjustmentStatus} action="APPROVE" role={user?.role || 'WH_KEEPER'}>
                  <Button 
                    onClick={() => setApproveDialogOpen(true)}
                    className="h-14 px-10 bg-emerald-600 hover:bg-emerald-500 text-white text-label-xs font-black uppercase tracking-widest rounded-2xl transition-all shadow-2xl shadow-emerald-600/30 border-none"
                  >
                    <CheckCircle className="w-5 h-5 me-3" />
                    {t('approve')}
                  </Button>
                </ActionGuard>

                <ActionGuard documentType="ADJUSTMENT" status={adjustmentStatus} action="POST" role={user?.role || 'WH_KEEPER'}>
                  <Button 
                    onClick={() => setPostDialogOpen(true)}
                    className="h-14 px-12 primary-gradient text-white text-label-xs font-black uppercase tracking-widest rounded-2xl transition-all shadow-2xl shadow-primary/30 border-none"
                  >
                    <CheckCircle className="w-5 h-5 me-3" />
                    {t('post_adjustment')}
                  </Button>
                </ActionGuard>
              </div>
            )
          }
        />
      </form>

      {/* Confirmation Dialogs */}
      <PostConfirmDialog
        open={submitDialogOpen}
        onOpenChange={setSubmitDialogOpen}
        title={t('submit_confirm_title')}
        description={t('submit_confirm_desc')}
        onConfirm={handleSubmit}
        isLoading={submitAdjustment.isPending}
      />

      <Dialog open={rejectDialogOpen} onOpenChange={setRejectDialogOpen}>
        <DialogContent className="bg-surface-container-lowest border-none shadow-2xl rounded-lg p-0 overflow-hidden max-w-md">
          <div className="p-8 space-y-6">
            <DialogHeader>
              <DialogTitle className="text-title-lg font-semibold uppercase italic text-red-500">{t('reject_title')}</DialogTitle>
              <DialogDescription className="text-label-sm font-medium text-muted-foreground">
                {t('reject_desc')}
              </DialogDescription>
            </DialogHeader>
            <Textarea
              value={rejectionComment}
              onChange={e => setRejectionComment(e.target.value)}
              placeholder={t('rejection_comment_placeholder')}
              className="bg-surface-container-highest border-none rounded-lg min-h-[120px] p-4 text-body-md resize-none"
            />
            {rejectionComment.trim().length > 0 && rejectionComment.trim().length < 15 && (
              <p className="text-label-xs font-semibold uppercase text-red-500 flex items-center gap-2">
                <AlertCircle className="w-3 h-3" />
                {t('min_chars_required', { count: 15 - rejectionComment.trim().length })}
              </p>
            )}
          </div>
          <DialogFooter className="p-8 bg-surface-container-low flex items-center justify-end gap-3">
            <Button variant="ghost" onClick={() => setRejectDialogOpen(false)} className="rounded-lg text-label-xs font-semibold uppercase">
              {tc('cancel')}
            </Button>
            <Button 
              onClick={handleReject}
              disabled={rejectionComment.trim().length < 15 || rejectAdjustment.isPending}
              className="bg-red-600 hover:bg-red-500 text-white rounded-lg h-12 px-8 text-label-xs font-semibold uppercase"
            >
              {t('confirm_rejection')}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <PostConfirmDialog
        open={approveDialogOpen}
        onOpenChange={setApproveDialogOpen}
        title={t('approve_confirm_title')}
        description={t('approve_confirm_desc')}
        onConfirm={handleApprove}
        isLoading={approveAdjustment.isPending}
      />

      <PostConfirmDialog
        open={postDialogOpen}
        onOpenChange={setPostDialogOpen}
        title={t('post_confirm_title')}
        description={t('post_confirm_desc')}
        warningText={t('post_irreversible')}
        requiresTextConfirmation={true}
        onConfirm={handlePost}
        isLoading={postAdjustment.isPending}
      />
    </div>
  );
}

'use client';

import { useTranslations } from 'next-intl';
import { useRouter } from '@/i18n/navigation';
import { useForm, useWatch } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { PageHeader } from '@/components/shared/PageHeader';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { Button } from '@/components/ui/button';
import { 
 Select, 
 SelectContent, 
 SelectItem, 
 SelectTrigger, 
 SelectValue 
} from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Input } from '@/components/ui/input';
import { useCreateAdjustment } from '@/features/operations/hooks/useCreateAdjustment';
import { useWarehouses } from '@/features/warehouses/api/useWarehouses';
import { useItems } from '@/features/items/api/useItems';
import { useWarehouseLock } from '@/hooks/useWarehouseLock';
import { LockBanner } from '@/components/shared/LockBanner';
import { Save, Package, Info, ArrowUp, ArrowDown } from 'lucide-react';
import { cn } from '@/lib/utils';

const REASON_OPTIONS = ['DAMAGE', 'EXPIRY', 'THEFT', 'COUNTING_ERROR', 'CORRECTION', 'OTHER'] as const;

const AdjustmentFormSchema = z.object({
 warehouse_id: z.string().min(1, 'Warehouse is required'),
 item_id: z.string().min(1, 'Item is required'),
 lot_number: z.string().optional(),
 quantity: z.number().positive('Quantity must be greater than zero'),
 direction: z.enum(['INCREASE', 'DECREASE']),
 reason_category: z.string().min(1, 'Reason category is required'),
 notes: z.string().min(10, 'Notes must be at least 10 characters'),
});

type AdjustmentFormValues = z.infer<typeof AdjustmentFormSchema>;

import { useUnsavedChangesGuard } from '@/lib/unsaved-changes/useUnsavedChangesGuard';

export function AdjustmentCreateClient({ locale }: { locale: 'ar' | 'en' }) {
 const t = useTranslations('operations.adjustment');
 const tCommon = useTranslations('common');
 
 const {
 register,
 handleSubmit,
 setValue,
 control,
 formState: { errors, isValid, isDirty },
 } = useForm<AdjustmentFormValues>({
 resolver: zodResolver(AdjustmentFormSchema),
 defaultValues: {
 direction: 'INCREASE',
 reason_category: 'DAMAGE',
 quantity: 1,
 }
 });

 const { router } = useUnsavedChangesGuard(isDirty);
 
 const { data: warehouses } = useWarehouses();
 const { data: items } = useItems();
 const createAdjustment = useCreateAdjustment();
 
 const selectedWarehouseId = useWatch({ control, name: 'warehouse_id' });
 const selectedItemId = useWatch({ control, name: 'item_id' });
 const { data: lockState } = useWarehouseLock(selectedWarehouseId);
 
 const selectedItem = items?.find(i => i.id === selectedItemId);
 const selectedDirection = useWatch({ control, name: 'direction' });

 const onSubmit = (data: AdjustmentFormValues) => {
   if (!!lockState?.isLocked) return;
   
   createAdjustment.mutate({
     warehouse_id: data.warehouse_id,
     reason: data.reason_category,
     notes: data.notes,
     lines: [{
       item_id: data.item_id,
       qty: data.quantity,
       uom_id: selectedItem?.uom || 'EA', // Use the UOM from selected item
       direction: data.direction,
       lot_allocations: data.lot_number ? [{ lot_id: data.lot_number, qty: data.quantity }] : undefined
     }]
   }, {
     onSuccess: () => {
       router.push("/adjustments", { skipGuard: true });
     }
   });
 };

 return (
 <div className="p-8 max-w-[1200px] mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-1000">
 <Breadcrumb 
 items={[
 { label: tCommon('inventory'), href: '#' },
 { label: t('title'), href: "/adjustments" },
 { label: t('create_new') }
 ]} 
 />
 
 <PageHeader
 title={t('create_new')}
 description={t('subtitle') || 'Inventory Calibrate Protocol'} actions={
 <Button 
 onClick={handleSubmit(onSubmit)} 
 disabled={!isValid || createAdjustment.isPending || !!lockState?.isLocked}
 className={cn(
 "bg-cyan-600 hover:bg-cyan-500 text-white rounded-xl h-11 px-8 text-label-xs font-semibold uppercase transition-all shadow-lg disabled:opacity-50"
 )}
 >
 <Save className="w-4 h-4 me-2" />
 {t('save_draft')}
 </Button>
 }
 />

 <LockBanner lockState={lockState} />

 <form className="grid grid-cols-1 md:grid-cols-2 gap-8">
 {/* Core Settings Panel */}
 <div className="bg-surface-container-low/50 p-8 rounded-[2rem] space-y-6 relative overflow-hidden">
 <div className="absolute top-0 inset-x-0 h-1 bg-gradient-to-e from-cyan-500/50 via-cyan-500/20 to-transparent" />
 
 <div className="flex items-center gap-3 mb-2">
 <Info className="w-4 h-4 text-cyan-500" />
 <h3 className={cn("text-label-xs font-semibold uppercase text-foreground/60")}>
 {t('details_section') || 'Document Details'}
 </h3>
 </div>

 {/* Warehouse Selection */}
 <div className="space-y-2">
 <label className={cn("text-label-xs font-semibold uppercase text-muted-foreground/60 ms-1")}>
 {tCommon('warehouse')}
 </label>
 <Select
 onValueChange={(val) => setValue('warehouse_id', (val as string) || '', { shouldValidate: true })}
 >
 <SelectTrigger className="w-full bg-surface-container-highest/40 rounded-xl h-[52px] font-bold text-body-md border-none hover:bg-surface-container-highest/60 transition-all outline-none ring-0 focus:ring-0 focus:bg-surface-container-highest/80">
 <SelectValue placeholder={tCommon('select_warehouse') || 'Select Warehouse'} />
 </SelectTrigger>
 <SelectContent className="bg-surface-container-highest rounded-xl shadow-2xl border-none">
 {warehouses?.map(w => (
 <SelectItem key={w.id} value={w.id} className="font-medium focus:bg-cyan-500/10 focus:text-cyan-400">
 {locale === 'ar' ? w.nameAr : w.nameEn}
 </SelectItem>
 ))}
 </SelectContent>
 </Select>
 {errors.warehouse_id && (
 <p className="text-label-xs font-bold text-red-500 uppercase ms-1">{errors.warehouse_id.message}</p>
 )}
 </div>

 {/* Reason Category */}
 <div className="space-y-2">
 <label className={cn("text-label-xs font-semibold uppercase text-muted-foreground/60 ms-1")}>
 {t('reason')}
 </label>
 <Select
 defaultValue="DAMAGE"
 onValueChange={(val) => setValue('reason_category', val || '', { shouldValidate: true })}
 >
 <SelectTrigger className="w-full bg-surface-container-highest/40 rounded-xl h-[52px] font-bold text-body-md border-none hover:bg-surface-container-highest/60 transition-all outline-none ring-0 focus:ring-0 focus:bg-surface-container-highest/80">
 <SelectValue />
 </SelectTrigger>
 <SelectContent className="bg-surface-container-highest rounded-xl shadow-2xl border-none">
 {REASON_OPTIONS.map(r => (
 <SelectItem key={r} value={r} className="font-medium focus:bg-cyan-500/10 focus:text-cyan-400">
 {t(`reasons.${r.toLowerCase()}`)}
 </SelectItem>
 ))}
 </SelectContent>
 </Select>
 {errors.reason_category && (
 <p className="text-label-xs font-bold text-red-500 uppercase ms-1">{errors.reason_category.message}</p>
 )}
 </div>

 {/* Adjustment Notes */}
 <div className="space-y-2">
 <label className={cn("text-label-xs font-semibold uppercase text-muted-foreground/60 ms-1")}>
 {tCommon('notes')}
 </label>
 <Textarea
 {...register('notes')}
 placeholder={t('notes_placeholder')}
