}

'use client';

import { useMemo } from 'react';
import { useTranslations } from 'next-intl';
import { useRouter, usePathname, Link } from '@/i18n/navigation';
import { useSearchParams } from 'next/navigation';
import { useKitchenRequestList, KitchenRequestSummary } from '@/features/operations/hooks/useKitchenRequests';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { StatusBadge } from '@/components/shared/StatusBadge';
import { format } from 'date-fns';
import { Button } from '@/components/ui/button';
import { DataTable } from '@/components/shared/DataTable/DataTable';
import { MetricCard } from '@/components/ui/metric-card';
import { ColumnDef } from '@tanstack/react-table';
import { 
 FileText, 
 Plus, 
 Warehouse, 
 Calendar, 
 ChefHat,
 Clock,
 CheckCircle2,
 AlertCircle
} from 'lucide-react';

import { PageHeader } from '@/components/shared/PageHeader';
import { Breadcrumb } from '@/components/shared/Breadcrumb';

import { isPendingStatus, isApprovedStatus, isCompletedStatus, type DocumentStatus } from '@/core/workflow/document-engine';
import { KITCHEN_REQUEST_STATUS } from '@/contracts/statuses';

export function KitchenRequestsListClient({
 initialStatus,
 initialDepartmentId,
 initialPage,
 locale
}: {
 initialStatus?: string;
 initialDepartmentId?: string;
 initialPage: number;
 locale: 'ar' | 'en'
}) {
 const t = useTranslations('operations.kitchen_request');
 const tc = useTranslations('common');
 const router = useRouter();
 const pathname = usePathname();
 const searchParams = useSearchParams();

 const { data, isLoading } = useKitchenRequestList({
 status: initialStatus,
 department_id: initialDepartmentId,
 page: initialPage
 });

 const columns = useMemo<ColumnDef<KitchenRequestSummary>[]>(() => [
 {
 accessorKey: 'request_number',
 header: t('doc_number'),
 cell: ({ row }) => (
 <div className="flex flex-col">
 <Link 
 href={`/kitchen-requests/${row.original.id}`}
 className="font-mono text-body-md font-semibold text-cyan-500 hover:text-cyan-400 transition-colors"
 >
 {row.original.request_number}
 </Link>
 <div className="flex items-center gap-1.5 opacity-20 mt-1">
 <Calendar className="w-2.5 h-2.5" />
 <span dir="ltr" className="text-label-xxs font-semibold tabular-nums">
 {format(new Date(row.original.created_at), 'MMM dd, HH:mm')}
 </span>
 </div>
 </div>
 ),
 },
 {
 accessorKey: 'department_id',
 header: t('department'),
 cell: ({ row }) => (
 <div className="flex items-center gap-2">
 <ChefHat className="w-3.5 h-3.5 text-muted-foreground/60" />
 <span className="font-bold text-label-sm text-foreground/80">{row.original.department_id}</span>
 </div>
 ),
 },
 {
 accessorKey: 'warehouse_id',
 header: t('warehouse'),
 cell: ({ row }) => (
 <div className="flex items-center gap-2">
 <Warehouse className="w-3.5 h-3.5 text-muted-foreground/60" />
 <span className="font-bold text-label-sm text-foreground/80">{row.original.warehouse_id}</span>
 </div>
 ),
 },
 {
 accessorKey: 'requested_by',
 header: t('requested_by'),
 cell: ({ row }) => (
 <span className="text-label-sm font-medium text-foreground/60">{row.original.requested_by}</span>
 ),
 },
 {
 accessorKey: 'status',
 header: t('status'),
 cell: ({ row }) => <StatusBadge status={row.original.status} />,
 },
 ], [t, tc]);

 const submittedCount = data?.data?.filter(doc => isPendingStatus('KITCHEN_REQUEST', doc.status as DocumentStatus)).length || 0;
 const approvedCount = data?.data?.filter(r => isApprovedStatus('KITCHEN_REQUEST', r.status)).length || 0;
 const completedCount = data?.data?.filter(doc => isCompletedStatus('KITCHEN_REQUEST', doc.status as DocumentStatus)).length || 0;
 const rejectedCount = data?.data?.filter(r => r.status === KITCHEN_REQUEST_STATUS.CANCELLED).length || 0;
 const fulfilledCount = data?.data?.filter(r => r.status === KITCHEN_REQUEST_STATUS.FULFILLED).length || 0;

 return (
 <div className="flex flex-col gap-6 p-6">
 <Breadcrumb
 items={[
 { label: tc('home'), href: '/' },
 { label: tc('operations'), href: '/operations' },
 { label: t('title') },
 ]}
 />

 <PageHeader
 title={t('title')}
 description={t('description')}
 actions={
 <PermissionGate action="create" resource="kitchen_requests">
 <Button 
 onClick={() => router.push('/kitchen-requests/new')}
 className="bg-cyan-600 hover:bg-cyan-500 text-white border-none shadow-[0_0_15px_rgba(8,145,178,0.3)] transition-all active:scale-95"
 >
 <Plus className="w-4 h-4 mr-2" />
 {t('create_new')}
 </Button>
 </PermissionGate>
 }
 />

 <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
 <MetricCard
 label={t('statuses.SUBMITTED')}
 value={submittedCount}
 icon={<Clock className="w-4 h-4" />}
 color="cyan"
 />
 <MetricCard
 label={t('statuses.APPROVED')}
 value={approvedCount}
 icon={<CheckCircle2 className="w-4 h-4" />}
 color="emerald"
 />
 <MetricCard
 label={t('statuses.REJECTED')}
 value={rejectedCount}
 icon={<AlertCircle className="w-4 h-4" />}
 color="rose"
 />
 <MetricCard
 label={t('statuses.FULFILLED')}
 value={fulfilledCount}
 icon={<FileText className="w-4 h-4" />}
 color="indigo"
 />
 </div>

 <div className="bg-surface-container-low rounded-xl border border-outline-low shadow-sm">
 <DataTable
 columns={columns}
 data={data?.data ?? []}
 isLoading={isLoading}
 pagination={{
 page: initialPage,
 pageSize: data?.meta?.page_size ?? 10,
 total: data?.meta?.total ?? 0,
 totalPages: data?.meta?.total_pages ?? 1,
 onPageChange: (page) => {
 const params = new URLSearchParams(searchParams.toString());
 params.set('page', (page + 1).toString());
 router.push(`${pathname}?${params.toString()}`);
 }
 }}
 />
 </div>
 </div>
 );
}

'use client';

import { useState, useMemo } from 'react';
import { useTranslations } from 'next-intl';
import { useRouter } from '@/i18n/navigation';
import { 
  ArrowLeft, 
  CheckCircle2, 
  XCircle, 
  PackageCheck, 
  Clock, 
  User, 
  Building2, 
  Warehouse, 
  FileText,
  History,
  AlertCircle
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { StatusBadge } from '@/components/shared/StatusBadge';
import { StatusTimeline, type StatusTimelineEntry } from '@/components/shared/StatusTimeline';
import { 
  useUpdateKitchenRequestStatus, 
  useFulfillKitchenRequest 
} from '@/features/operations/hooks/useKitchenRequests';
import { 
  Dialog, 
  DialogContent, 
  DialogHeader, 
  DialogTitle, 
  DialogFooter,
  DialogDescription
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { cn } from '@/lib/utils';
import type { Status } from '@/components/shared/StatusTimeline';
import { useAuth } from '@/providers/AuthProvider';
import { DocumentLockBanner, DocumentLockWrapper } from '@/components/shared/DocumentLockBanner';
import { FormFooter } from '@/components/shared/FormFooter';
import { 
  canPerformActionV2,
  isDocumentLocked,
  DocumentStatus 
} from '@/core/workflow/document-engine';
import { ActionGuard } from '@/core/workflow/ActionGuard';
import { KITCHEN_REQUEST_STATUS } from '@/contracts/statuses';

interface KitchenRequestFormProps {
  request: any;
  locale: 'ar' | 'en';
}

export function KitchenRequestForm({ request, locale }: KitchenRequestFormProps) {
  const t = useTranslations('operations.kitchen_request');
  const tCommon = useTranslations('common');
  const router = useRouter();
  const { user } = useAuth();
  const id = request.id;
  
  const updateStatus = useUpdateKitchenRequestStatus();
  const fulfillRequest = useFulfillKitchenRequest();
  
  const [rejectDialogOpen, setRejectDialogOpen] = useState(false);
  const [rejectionReason, setRejectionReason] = useState('');
  
  const [fulfillDialogOpen, setFulfillDialogOpen] = useState(false);
  const [fulfillmentData, setFulfillmentData] = useState<{ itemId: string; fulfilledQuantity: number }[]>([]);

  const history = useMemo((): StatusTimelineEntry[] => {
    const h: StatusTimelineEntry[] = [
      { status: 'draft' as Status, at: request.created_at, by: request.requested_by }
    ];
    if (!canPerformActionV2('KITCHEN_REQUEST', request.status as DocumentStatus, 'SUBMIT', user?.role)) {
      h.push({ status: 'submitted' as Status, at: request.requested_at, by: request.requested_by });
    }
    if (request.approved_at) {
      h.push({ status: 'approved' as Status, at: request.approved_at, by: request.approved_by || 'Approver' });
    }
    if (request.rejected_at) {
      h.push({ status: 'rejected' as Status, at: request.rejected_at, by: request.rejected_by || 'Rejecter' });
    }
    if (request.fulfilled_at) {
      h.push({ status: request.status.toLowerCase() as Status, at: request.fulfilled_at, by: request.fulfilled_by || 'Store Keeper' });
    }
    return h;
  }, [request, user?.role]);

  const handleApprove = async () => {
    try {
      await updateStatus.mutateAsync({ id, status: KITCHEN_REQUEST_STATUS.APPROVED as any, version: request.version ?? 0 });
    } catch (error) {
      console.error('Failed to approve request', error);
    }
  };

  const handleReject = async () => {
    if (!rejectionReason.trim()) return;
    try {
      await updateStatus.mutateAsync({ id, status: KITCHEN_REQUEST_STATUS.CANCELLED as any, reason: rejectionReason, version: request.version ?? 0 });
      setRejectDialogOpen(false);
    } catch (error) {
      console.error('Failed to reject request', error);
    }
  };

  const handleFulfill = async () => {
    try {
      await fulfillRequest.mutateAsync({ id, items: fulfillmentData, version: request.version ?? 0 });
      setFulfillDialogOpen(false);
    } catch (error) {
      console.error('Failed to fulfill request', error);
    }
  };

  const openFulfillDialog = () => {
    setFulfillmentData(
      request.items.map((item: any) => ({
        itemId: item.item_id,
        fulfilledQuantity: item.quantity
      }))
    );
    setFulfillDialogOpen(true);
  };

  const status = request.status as DocumentStatus;
  const isDocLocked = isDocumentLocked('KITCHEN_REQUEST', status);
  const isPending = updateStatus.isPending || fulfillRequest.isPending;


  const workflowActions = (
    <>
      <ActionGuard documentType="KITCHEN_REQUEST" status={status} action="REJECT" role={user?.role || 'WH_KEEPER'}>
        <Button 
          variant="outline" 
          disabled={isPending}
          className="rounded-lg border-red-500/30 text-red-500 hover:bg-red-500/5 h-12 px-6 text-label-xs font-semibold uppercase"
          onClick={() => setRejectDialogOpen(true)}
        >
          <XCircle className="w-4 h-4 me-2" />
          {t('reject')}
        </Button>
      </ActionGuard>
      <ActionGuard documentType="KITCHEN_REQUEST" status={status} action="APPROVE" role={user?.role || 'WH_KEEPER'}>
        <Button 
          disabled={isPending}
          className="bg-emerald-600 hover:bg-emerald-500 text-white rounded-lg h-12 px-8 text-label-xs font-semibold uppercase shadow-lg shadow-emerald-900/20"
          onClick={handleApprove}
        >
          <CheckCircle2 className="w-4 h-4 me-2" />
          {t('approve')}
        </Button>
      </ActionGuard>
      <ActionGuard documentType="KITCHEN_REQUEST" status={status} action="FULFILL" role={user?.role || 'WH_KEEPER'}>
        <Button 
          disabled={isPending}
          className="bg-cyan-600 hover:bg-cyan-500 text-white rounded-lg h-12 px-10 text-label-xs font-semibold uppercase shadow-xl shadow-cyan-900/20"
          onClick={openFulfillDialog}
        >
          <PackageCheck className="w-4 h-4 me-2" />
          {t('fulfill')}
        </Button>
      </ActionGuard>
    </>
  );

  return (
    <div className="min-h-screen bg-surface-container-low flex flex-col animate-in fade-in duration-1000 pb-32">
      <div className="max-w-[1400px] mx-auto px-6 lg:px-10 py-10 w-full space-y-8">
        <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
          <div className="space-y-4">
            <Breadcrumb 
              items={[
                { label: tCommon('inventory'), href: '#' },
                { label: t('title'), href: "/kitchen-requests" },
                { label: request.request_number }
              ]} 
            />
            <div className="flex items-center gap-4">
              <Button variant="ghost" size="icon" onClick={() => router.back()} className="rounded-lg">
                <ArrowLeft className={cn("w-5 h-5", locale === 'ar' && "rotate-180")} />
              </Button>
              <div>
                <h1 className="text-headline-lg font-semibold uppercase italic">{request.request_number}</h1>
                <div className="flex items-center gap-3 mt-1">
                  <StatusBadge status={request.status} />
                  <span className="text-label-xs font-semibold uppercase text-muted-foreground/40 flex items-center gap-1.5">
                    <Clock className="w-3 h-3" />
                    {new Date(request.created_at).toLocaleString()}
                  </span>
                </div>
              </div>
            </div>
          </div>
        </div>

        <form 
          onSubmit={(e) => e.preventDefault()}
          className="space-y-10"
        >
          <DocumentLockBanner isLocked={isDocLocked} status={status} />

          <DocumentLockWrapper isLocked={isDocLocked && status !== KITCHEN_REQUEST_STATUS.SUBMITTED}>
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
              {/* Left Column: Details and Items */}
              <div className="lg:col-span-8 space-y-8">
                <div className="bg-surface-container-lowest p-8 rounded-lg border border-surface-container-high/20 grid grid-cols-1 md:grid-cols-3 gap-8">
                  <div className="space-y-1">
                    <span className="text-label-xs font-semibold uppercase text-muted-foreground/40 flex items-center gap-2">
                      <Building2 className="w-3.5 h-3.5" />
                      {t('department')}
                    </span>
                    <p className="text-body-md font-bold">{request.department_name}</p>
                  </div>
                  <div className="space-y-1">
                    <span className="text-label-xs font-semibold uppercase text-muted-foreground/40 flex items-center gap-2">
                      <Warehouse className="w-3.5 h-3.5" />
                      {t('warehouse')}
                    </span>
                    <p className="text-body-md font-bold">{request.warehouse_name}</p>
                  </div>
                  <div className="space-y-1">
                    <span className="text-label-xs font-semibold uppercase text-muted-foreground/40 flex items-center gap-2">
                      <User className="w-3.5 h-3.5" />
                      {t('requested_by')}
                    </span>
                    <p className="text-body-md font-bold">{request.requested_by}</p>
                  </div>
                  {request.notes && (
                    <div className="md:col-span-3 pt-4 border-t border-surface-container-high/50 space-y-1">
                      <span className="text-label-xs font-semibold uppercase text-muted-foreground/40 flex items-center gap-2">
                        <FileText className="w-3.5 h-3.5" />
                        {tCommon('notes')}
                      </span>
                      <p className="text-label-sm text-muted-foreground italic leading-relaxed">&quot;{request.notes}&quot;</p>
                    </div>
                  )}
                  {status !== KITCHEN_REQUEST_STATUS.DRAFT && request.rejection_reason && (
                    <div className="md:col-span-3 p-4 bg-red-500/5 border border-red-500/10 rounded-lg space-y-1">
                      <span className="text-label-xs font-semibold uppercase text-red-500/60 flex items-center gap-2">
                        <AlertCircle className="w-3.5 h-3.5" />
                        {t('rejection_reason_label')}
                      </span>
                      <p className="text-label-sm font-bold text-red-500">{request.rejection_reason}</p>
                    </div>
                  )}
                </div>

                <div className="bg-surface-container-lowest rounded-lg border border-surface-container-high/20 overflow-hidden">
                  <div className="p-8 border-b border-surface-container-high/50 flex justify-between items-center">
                    <div className="flex items-center gap-4">
                      <div className="w-1.5 h-6 bg-cyan-500 rounded-full" />
                      <h3 className="text-label-sm font-semibold uppercase">{t('items')}</h3>
                    </div>
                    <Badge variant="outline" className="rounded-lg text-label-xxs font-semibold px-3 py-1 border-none bg-surface-container-high text-muted-foreground/60">
                      {request.items.length} {t('entries')}
                    </Badge>
                  </div>
                  <div className="overflow-x-auto">
                    <table className="w-full text-left rtl:text-right border-collapse">
                      <thead>
                        <tr className="bg-surface-container-high/30">
                          <th className="px-8 py-5 text-label-xs font-semibold uppercase text-muted-foreground/60">{tCommon('item')}</th>
                          <th className="px-8 py-5 text-label-xs font-semibold uppercase text-muted-foreground/60 text-center">{tCommon('quantity')}</th>
                          <ActionGuard documentType="KITCHEN_REQUEST" status={status} action="INTERNAL_MOVEMENT" role={user?.role || 'WH_KEEPER'}>
                            <th className="px-8 py-5 text-label-xs font-semibold uppercase text-muted-foreground/60 text-center">{t('fulfilled')}</th>
                          </ActionGuard>
                          <th className="px-8 py-5 text-label-xs font-semibold uppercase text-muted-foreground/60">{tCommon('notes')}</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-surface-container-high/30">
                        {request.items.map((item: any) => (
                          <tr key={item.id} className="group hover:bg-surface-container-medium/30 transition-all">
                            <td className="px-8 py-6">
                              <div className="flex flex-col">
                                <span className="text-label-sm font-bold text-foreground">{item.item_name}</span>
                                <span className="text-label-xxs font-mono text-muted-foreground/40 mt-1 uppercase">ID: {item.item_id}</span>
                              </div>
                            </td>
                            <td className="px-8 py-6 text-center">
                              <div className="flex flex-col items-center gap-0.5">
                                <span className="text-body-md font-semibold text-cyan-500 tabular-nums">{item.quantity}</span>
                                <span className="text-label-xxs font-semibold uppercase text-muted-foreground/30">{item.uom}</span>
                              </div>
                            </td>
                              <ActionGuard documentType="KITCHEN_REQUEST" status={status} action="INTERNAL_MOVEMENT" role={user?.role || 'WH_KEEPER'}>
                                <td className="px-8 py-6 text-center">
                                  <div className="flex flex-col items-center gap-0.5">
                                    <span className={cn(
                                      "text-body-md font-semibold tabular-nums",
                                      (item.fulfilled_quantity || 0) < item.quantity ? "text-amber-500" : "text-emerald-500"
                                    )}>{item.fulfilled_quantity || 0}</span>
                                    <span className="text-label-xxs font-semibold uppercase text-muted-foreground/30">{item.uom}</span>
                                  </div>
                                </td>
                              </ActionGuard>
                            <td className="px-8 py-6">
                              <p className="text-label-xs font-medium text-muted-foreground/60 max-w-[200px] line-clamp-2 italic">
                                {item.notes || 'ظ¤'}
                              </p>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>

              {/* Right Column: Timeline and Meta */}
              <div className="lg:col-span-4 space-y-8">
                <div className="bg-surface-container-lowest p-8 rounded-lg border border-surface-container-high/20 relative overflow-hidden group">
                  <div className="absolute top-0 end-0 w-32 h-32 bg-cyan-500/5 blur-[50px] -me-16 -mt-16 rounded-full group-hover:bg-cyan-500/10 transition-all duration-700" />
                  <div className="relative space-y-8">
                    <div className="flex items-center gap-4">
                      <div className="w-10 h-10 rounded-lg bg-cyan-500/10 flex items-center justify-center">
                        <History className="w-5 h-5 text-cyan-500" />
                      </div>
                      <h4 className="text-label-xs font-semibold uppercase">{tCommon('history')}</h4>
                    </div>
                    <div className="ps-2">
                      <StatusTimeline entries={history} />
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </DocumentLockWrapper>

          <FormFooter 
            isLocked={isDocLocked && status !== KITCHEN_REQUEST_STATUS.SUBMITTED}
            onCancel={() => router.push('/kitchen-requests')}
            actions={workflowActions}
            isSaving={isPending}
          />
        </form>
      </div>

      {/* Dialogs */}
      <Dialog open={rejectDialogOpen} onOpenChange={setRejectDialogOpen}>
        <DialogContent className="bg-surface-container-lowest border-none shadow-2xl rounded-lg p-0 overflow-hidden max-w-md">
          <div className="p-8 space-y-6">
            <DialogHeader>
              <DialogTitle className="text-title-lg font-semibold uppercase italic text-red-500">{t('reject')}</DialogTitle>
              <DialogDescription className="text-label-sm font-medium text-muted-foreground">
                {t('rejection_reason_description') || "Please provide a reason for rejecting this request."}
              </DialogDescription>
            </DialogHeader>
            <Textarea 
              placeholder={t('rejection_reason_placeholder')}
              className="bg-surface-container-highest border-none rounded-lg p-5 text-body-md min-h-[120px] transition-all"
              value={rejectionReason}
              onChange={(e) => setRejectionReason(e.target.value)}
            />
          </div>
          <DialogFooter className="p-8 bg-surface-container-low flex items-center justify-end gap-3">
            <Button variant="ghost" onClick={() => setRejectDialogOpen(false)} className="rounded-lg text-label-xs font-semibold uppercase">{t('cancel')}</Button>
            <Button 
              className="bg-red-600 hover:bg-red-500 text-white rounded-lg h-12 px-8 text-label-xs font-semibold uppercase"
              onClick={handleReject}
              disabled={!rejectionReason.trim()}
            >
              {t('confirm_rejection')}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={fulfillDialogOpen} onOpenChange={setFulfillDialogOpen}>
        <DialogContent className="bg-surface-container-lowest border-none shadow-2xl rounded-lg p-0 overflow-hidden max-w-2xl">
          <div className="p-8 space-y-6">
            <DialogHeader>
              <DialogTitle className="text-title-lg font-semibold uppercase italic text-cyan-500">{t('fulfill')}</DialogTitle>
              <DialogDescription className="text-label-sm font-medium text-muted-foreground">
                {t('fulfillment_desc')}
              </DialogDescription>
            </DialogHeader>
            <div className="space-y-4 max-h-[50vh] overflow-y-auto pr-2">
              {request.items.map((item: any) => (
                <div key={item.id} className="grid grid-cols-[2fr_1fr_1fr] gap-4 items-center p-4 bg-surface-container-high/30 rounded-lg border border-surface-container-high/50">
                  <div className="space-y-1">
                    <p className="text-label-sm font-bold">{item.item_name}</p>
                    <p className="text-label-xxs font-semibold text-muted-foreground/40 uppercase">{t('requested')}: {item.quantity} {item.uom}</p>
                  </div>
                  <div className="text-center">
                    <span className="text-label-xxs font-semibold text-muted-foreground/60 uppercase mb-1 block">{t('fulfilling')}</span>
                    <Input 
                      type="number"
                      step="0.01"
                      dir="ltr"
                      className="bg-surface-container-highest border-none h-10 text-center font-semibold text-body-md rounded-lg transition-all"
                      value={fulfillmentData.find(f => f.itemId === item.item_id)?.fulfilledQuantity || 0}
                      onChange={(e) => {
                        const val = Number(e.target.value);
                        setFulfillmentData(prev => prev.map(f => f.itemId === item.item_id ? { ...f, fulfilledQuantity: val } : f));
                      }}
                    />
                  </div>
                  <div className="text-center pt-4">
                    <span className="text-label-xxs font-semibold uppercase text-muted-foreground/30">{item.uom}</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
          <DialogFooter className="p-8 bg-surface-container-low flex items-center justify-end gap-3">
            <Button variant="ghost" onClick={() => setFulfillDialogOpen(false)} className="rounded-lg text-label-xs font-semibold uppercase">{t('cancel')}</Button>
            <Button 
              className="bg-cyan-600 hover:bg-cyan-500 text-white rounded-lg h-12 px-10 text-label-xs font-semibold uppercase shadow-lg shadow-cyan-900/20"
              onClick={handleFulfill}
            >
              {t('post_fulfillment')}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

'use client';

import { useTranslations } from 'next-intl';
import { useUnsavedChangesGuard } from '@/lib/unsaved-changes/useUnsavedChangesGuard';
import { useState, useEffect } from 'react';
import { useForm, useFieldArray, useWatch } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { PageHeader } from '@/components/shared/PageHeader';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { Button } from '@/components/ui/button';
import { 
 Select, 
 SelectContent, 
 SelectItem, 
 SelectTrigger, 
 SelectValue 
} from '@/components/ui/select';
import { Input } from '@/components/ui/input';
import { useCreateKitchenRequest } from '@/features/operations/hooks/useKitchenRequests';
import { useWarehouses } from '@/features/warehouses/api/useWarehouses';
import { useDepartments } from '@/features/departments/hooks/useDepartments';
import { useItems } from '@/features/items/api/useItems';
import { 
 Plus, 
 Trash2, 
 Save, 
 Send, 
 Warehouse, 
 Building2, 
 FileText,
 Package,
 Calculator,
 ListFilter
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { 
 KitchenRequestSchema, 
 CreateKitchenRequestDTO 
} from '@/features/operations/types/kitchen-request';

type KitchenRequestFormValues = CreateKitchenRequestDTO;

export function KitchenRequestFormClient({ locale }: { locale: 'ar' | 'en' }) {
 const t = useTranslations('operations.kitchen_request');
 const tCommon = useTranslations('common');
 
 const form = useForm<KitchenRequestFormValues>({
 resolver: zodResolver(KitchenRequestSchema),
 defaultValues: {
 items: [{ itemId: '', quantity: 1, notes: '' }],
 }
 });

  const { router: guardedRouter } = useUnsavedChangesGuard(form.formState.isDirty);
 
 const { data: warehouses } = useWarehouses();
 const { data: departments } = useDepartments();
 const { data: items } = useItems();
 const createRequest = useCreateKitchenRequest();
 
 const { fields, append, remove } = useFieldArray({
 control: form.control,
 name: "items"
 });
 
 const watchedItems = useWatch({
 control: form.control,
 name: "items",
 });

  const onSubmit = (values: KitchenRequestFormValues, isDraft: boolean) => {
    createRequest.mutate({ ...values, isDraft }, {
      onSuccess: () => {
        guardedRouter.push('/kitchen-requests', { skipGuard: true });
      }
    });
  };

  return (
    <div className="p-8 max-w-[1200px] mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-1000">
      <Breadcrumb 
        items={[
          { label: tCommon('inventory'), href: '#' },
          { label: t('title'), href: '/kitchen-requests' },
          { label: t('create_new') }
        ]} 
      />
 
 <PageHeader
 title={t('create_new')}
 description={t('new_description')}
 actions={
 <div className="flex items-center gap-3">
 <Button 
 variant="outline"
 onClick={form.handleSubmit((data) => onSubmit(data, true))} 
 disabled={createRequest.isPending}
 className="rounded-xl h-11 px-6 text-label-xs font-semibold uppercase transition-all"
 >
 <Save className="w-4 h-4 me-2" />
 {t('save_draft')}
 </Button>
 <Button 
 onClick={form.handleSubmit((data) => onSubmit(data, false))} 
 disabled={createRequest.isPending}
 className={cn(
 "bg-cyan-600 hover:bg-cyan-500 text-white rounded-xl h-11 px-8 text-label-xs font-semibold uppercase transition-all shadow-lg"
 )}
 >
 <Send className="w-4 h-4 me-2" />
