'use client';
 
import { useMemo } from 'react';

import { useTranslations } from 'next-intl';
import { useRouter, usePathname, Link } from '@/i18n/navigation';
import { useSearchParams } from 'next/navigation';
import { useStocktakeList, StocktakeSummary } from '@/features/operations/hooks/useStocktakeList';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { StatusBadge } from '@/components/shared/StatusBadge';
import { format } from 'date-fns';
import { Button } from '@/components/ui/button';
import { DataTable } from '@/components/shared/DataTable/DataTable';
import { MetricCard } from '@/components/ui/metric-card';
import { EmptyState } from '@/components/shared/EmptyState';
import { ColumnDef } from '@tanstack/react-table';
import { FileText, ClipboardCheck, AlertCircle, Plus, Filter, Search, Warehouse, Calendar, History } from 'lucide-react';

import { PageHeader } from '@/components/shared/PageHeader';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { isStocktakeInProgress, isStocktakePosted } from '@/domain/status-guards';
import { STOCKTAKE_STATUS_UI, getStatusConfig } from '@/domain/status-ui-map';
import { QueryBoundary } from '@/core/query/QueryBoundary';
import { PageSkeleton } from '@/components/shared/PageSkeleton';
import { STOCKTAKE_STATUS } from '@/contracts/statuses';

export function StocktakeListClient({
 initialStatus,
 initialPage,
 initialWarehouseId,
 locale
}: {
 initialStatus?: string;
 initialPage: number;
 initialWarehouseId?: string;
 locale: 'ar' | 'en'
}) {
 const t = useTranslations('operations.stocktake');
 const router = useRouter();
 const pathname = usePathname();
 const searchParams = useSearchParams();
 const tc = useTranslations('common');

 const { data, isLoading } = useStocktakeList({
 status: initialStatus,
 warehouse_id: initialWarehouseId,
 page: initialPage
 });

 const handleStatusChange = (val: string | null) => {
 const params = new URLSearchParams(searchParams.toString());
 if (val && val !== 'ALL') {
 params.set('status', val);
 } else {
 params.delete('status');
 }
 params.set('page', '1');
 router.push(`${pathname}?${params.toString()}`);
 };

 const handlePageChange = (newPage: number) => {
 const params = new URLSearchParams(searchParams.toString());
 params.set('page', newPage.toString());
 router.push(`${pathname}?${params.toString()}`);
 };

 const columns = useMemo<ColumnDef<StocktakeSummary>[]>(() => [
 {
 accessorKey: 'session_number',
 header: t('session_number') || 'Session',
 cell: ({ row }) => (
 <div className="flex flex-col">
 <span dir="ltr" className="font-mono text-body-md font-semibold text-cyan-500 group-hover:text-cyan-400 transition-colors">
 {row.original.session_number}
 </span>
 <span className="text-label-xxs font-semibold text-muted-foreground/40 uppercase">
 Operational Audit
 </span>
 <div className="flex items-center gap-1.5 opacity-20 mt-1">
 <Calendar className="w-2.5 h-2.5" />
 <span dir="ltr" className="text-label-xxs font-semibold tabular-nums">
 {format(new Date(row.original.snapshot_at), 'MMM dd, HH:mm')}
 </span>
 </div>
 </div>
 ),
 },
 {
 accessorKey: 'warehouse_id',
 header: tc('warehouse') || 'Warehouse',
 cell: ({ row }) => (
 <div className="flex items-center gap-2">
 <div className="w-7 h-7 rounded-lg bg-surface-container-highest/30 flex items-center justify-center border border-outline-low">
 <Warehouse className="w-3.5 h-3.5 text-muted-foreground/60" />
 </div>
 <span className="font-bold text-label-sm text-foreground/80">{row.original.warehouse_id}</span>
 </div>
 ),
 },
 {
 accessorKey: 'status',
 header: tc('status_label') || 'State',
 cell: ({ row }) => <StatusBadge status={row.original.status} />,
 },
 {
 id: 'actions',
 header: '',
 cell: ({ row }) => (
 <div className="flex justify-end pe-4">
 <Button
 variant="ghost"
 size="sm"
 className="h-8 px-4 text-label-xxs font-semibold uppercase text-cyan-500 hover:text-cyan-400 hover:bg-cyan-500/10 rounded-md group/btn transition-all"
 onClick={(e) => {
 e.stopPropagation();
 router.push(`/stocktake/${row.original.id}`);
 }}
 >
 {tc('view') || 'Inspect'}
 <Plus className="w-3 h-3 ms-2 group-hover/btn:rotate-90 transition-transform" />
 </Button>
 </div>
 ),
 },
 ], [t, tc, locale, router]);

  const activeSessionsCount = data?.meta?.total || 0;
  const inProgressCount = data?.data?.filter(i => isStocktakeInProgress(i.status)).length || 0;
  const postedCount = data?.data?.filter(i => isStocktakePosted(i.status)).length || 0;

 return (
 <div className="p-8 max-w-[1600px] mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-1000">
 <div className="flex flex-col gap-6">
 <Breadcrumb 
 items={[
 { label: tc('inventory'), href: '#' },
 { label: t('title'), href: `/stocktake` }
 ]} 
 />
 <PageHeader
 title={t('title')}
 description={t('description') || 'Physical inventory verification and variance auditing'} actions={
 <div className="flex items-center gap-8">
 <div className="flex flex-col items-end gap-1 border-e border-outline-low pe-8 hidden md:flex">
 <div className="text-label-xs font-semibold uppercase text-cyan-500 flex items-center gap-2">
 <span className="w-1.5 h-1.5 rounded-full bg-cyan-500 animate-pulse shadow-[0_0_10px_rgba(6,182,212,1)]" />
 {tc('status.live_updates')}
 </div>
 <div dir="ltr" className="text-label-xxs font-bold text-muted-foreground/30 flex items-center gap-1.5">
 <History className="w-2.5 h-2.5" />
 {tc('status.last_sync')}: {new Date().toLocaleTimeString()}
 </div>
 </div>
 <PermissionGate action="create" resource="stocktake">
 <Link href={`/stocktake/new`}>
 <Button className="h-12 px-10 bg-cyan-600 hover:bg-cyan-500 text-white text-label-xs font-semibold uppercase rounded-md transition-all shadow-xl shadow-cyan-900/20 group">
 <Plus className="w-4 h-4 me-2 group-hover:rotate-90 transition-transform" />
 {t('create_new')}
 </Button>
 </Link>
 </PermissionGate>
 </div>
 }
 />
 </div>

 <QueryBoundary 
        isLoading={isLoading} 
        error={data === undefined && !isLoading ? new Error('Failed to load data') : null}
        loadingFallback={<PageSkeleton />}
      >
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <MetricCard
            label={t('total_sessions')}
            value={activeSessionsCount}
            icon={FileText}
            trend="active"
          />
          <MetricCard
            label={t('in_progress')}
            value={inProgressCount}
            icon={AlertCircle}
            trend="active"
            color="amber"
          />
          <MetricCard
            label={t('posted')}
            value={postedCount}
            icon={ClipboardCheck}
            trend="active"
            color="emerald"
          />
        </div>

        <div className="space-y-6">
          <div className="flex flex-wrap items-end gap-6 w-full p-8 bg-surface-container-low rounded-lg border border-outline-low shadow-2xl">
            <div className="flex flex-col gap-3 min-w-[280px] flex-1">
              <div className="flex items-center gap-2 ms-1">
                <Filter className="w-3 h-3 text-cyan-500/60" />
                <label className="text-label-xs font-semibold uppercase text-muted-foreground/40">{tc('status_label') || 'Filter by State'}</label>
              </div>
              <Select
                value={initialStatus || 'ALL'} 
                onValueChange={handleStatusChange}
              >
                <SelectTrigger className="w-full bg-surface-container-highest/20 border-outline-low h-12 px-5 text-label-sm font-semibold rounded-md focus:ring-cyan-500/20 hover:bg-surface-container-highest/40 transition-all">
                  <SelectValue placeholder={tc('status.all')} />
                </SelectTrigger>
                 <SelectContent className="bg-surface-container-high border-outline-low/10 rounded-xl shadow-2xl">
                   <SelectItem value="ALL" className="text-label-sm font-bold uppercase">{tc('status.all')}</SelectItem>
                   {Object.values(STOCKTAKE_STATUS).map((value) => {
                     const config = getStatusConfig(value, STOCKTAKE_STATUS_UI);
                     return (
                       <SelectItem key={value} value={value} className="text-label-sm font-bold uppercase">
                         {tc(config.labelKey)}
                       </SelectItem>
                     );
                   })}
                 </SelectContent>
              </Select>
            </div>

            <div className="flex flex-col gap-3 min-w-[340px] flex-[2]">
              <div className="flex items-center gap-2 ms-1">
                <Search className="w-3 h-3 text-cyan-500/60" />
                <label className="text-label-xs font-semibold uppercase text-muted-foreground/40">{tc('search')}</label>
              </div>
              <div className="relative group">
                <input
                  placeholder={t('search_placeholder') || 'Search by Session ID...'} 
                  className="w-full bg-surface-container-highest/20 border border-outline-low h-12 px-6 text-label-sm font-semibold rounded-md outline-none focus:ring-2 focus:ring-cyan-500/30 transition-all placeholder:text-muted-foreground/20 group-hover:bg-surface-container-highest/40"
                />
              </div>
            </div>

            <Button className="h-12 px-8 bg-surface-container-highest/40 hover:bg-surface-container-highest/60 text-foreground/60 text-label-xs font-semibold uppercase rounded-md transition-all border border-outline-low hover:text-foreground">
              {tc('filters_button')}
            </Button>
          </div>

          <div className="bg-surface-container-lowest rounded-lg border border-outline-low overflow-hidden shadow-2xl">
            <DataTable
              columns={columns}
              data={data?.data || []}
              isLoading={false}
              onRowClick={(row: StocktakeSummary) => router.push(`/stocktake/${row.id}`)}
              collectionName="operations_stocktake"
              enableVirtualization={true}
              containerHeight="600px"
              emptyState={
                <EmptyState 
                  title={t('no_records') || 'No Stocktakes Found'} 
                  description={t('description') || 'Physical inventory verification sessions will appear here.'} 
                  action={
                    <PermissionGate action="create" resource="stocktake">
                      <Button 
                        onClick={() => router.push(`/stocktake/new`)}
                        className="bg-cyan-500/10 hover:bg-cyan-500/20 text-cyan-500 border border-cyan-500/20"
                      >
                        <Plus className="w-4 h-4 me-2" />
                        {t('create_new')}
                      </Button>
                    </PermissionGate>
                  }
                />
              }
              pagination={data?.meta ? {
                page: data.meta.page,
                pageSize: data.meta.page_size,
                total: data.meta.total,
                totalPages: data.meta.total_pages,
                onPageChange: handlePageChange
              } : undefined}
            />
          </div>
        </div>
      </QueryBoundary>
 </div>
 );
}

"use client"

import * as React from "react";
import { useWarehouses } from "@/features/warehouses/api/useWarehouses";
import { useWarehouseLock } from "@/hooks/useWarehouseLock";
import { useTranslations } from "next-intl";
import { useRouter } from "@/i18n/navigation";
import { format } from "date-fns";
import { 
  Clock, 
  Warehouse, 
  User, 
  ClipboardList, 
  History
} from "lucide-react";
import { useAuth } from "@/providers/AuthProvider";
import { cn } from "@/lib/utils";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Breadcrumb } from "@/components/shared/Breadcrumb";
import { LockBanner } from "@/components/shared/LockBanner";
import { StatusTimeline } from "@/components/shared/StatusTimeline";
import { DocumentStatus } from "@/types/DocumentStatus";
import { ActionGuard } from "@/core/workflow/ActionGuard";
import { STOCKTAKE_STATUS } from "@/contracts/statuses";
import { isStocktakeCounting, isStocktakeInReview } from "@/domain/status-guards";
import { STOCKTAKE_STATUS_UI } from "@/domain/status-ui-map";
import { StatusBadge } from "@/components/shared/StatusBadge";

import { DocumentLockBanner } from "@/components/shared/DocumentLockBanner";
import { FormFooter } from "@/components/shared/FormFooter";

import { StocktakeSessionVM, StocktakeItemVM } from "@/features/operations/mappers/stocktakeMapper";

interface StocktakeFormProps {
  session: StocktakeSessionVM;
  locale: 'ar' | 'en';
  actions: React.ReactNode;
  isLocked?: boolean;
  onConflict?: (error: any) => void;
}

export function StocktakeForm({ session, locale, actions, isLocked = false }: StocktakeFormProps) {
  const t = useTranslations('operations.stocktake')
  const common = useTranslations('common')
  const router = useRouter();
  const { user } = useAuth();
  const { data: warehouses } = useWarehouses();
  const { data: lockState } = useWarehouseLock(session?.warehouseId ?? null);

  const status = session.status as DocumentStatus;
  const warehouse = warehouses?.find(w => w.id === session.warehouseId);
  const warehouseName = warehouse ? (locale === 'ar' ? warehouse.nameAr : warehouse.nameEn) : (session.warehouseName || session.warehouseId);

  // Note: We use canPerformAction directly for internal flags where ActionGuard (JSX) isn't appropriate
  const isCounting = isStocktakeCounting(status) || status === STOCKTAKE_STATUS.STARTED;

  return (
    <div className="min-h-screen bg-surface-container-low pb-12 animate-in fade-in duration-500">
      {/* Sticky Glass Header */}
      <div className="sticky top-0 z-50 w-full glass-header border-b border-outline-variant/50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex flex-col">
            <Breadcrumb
              items={[
                { label: t('title'), href: `/stocktake` },
                { label: session.sessionName },
              ]}
            />
            <div className="flex items-center gap-2">
              <h1 className="font-semibold text-title-sm">
                {session.sessionName}
              </h1>
              <StatusBadge 
                status={session.status} 
                configMap={STOCKTAKE_STATUS_UI}
                className="h-6 px-2 text-label-xxs font-semibold border-none" 
              />
            </div>
          </div>

          {actions}
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-6 space-y-6">
        <DocumentLockBanner 
          status={session.status} 
          isLocked={isLocked} 
        />

        {/* Form Content Wrapper with Visual Locking */}
        <div className={cn(
          "space-y-6 transition-all duration-500",
          isLocked && "opacity-60 grayscale-[0.2] pointer-events-none select-none"
        )}>
          {/* Metadata Grid */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            {[
              { label: common('warehouse'), value: warehouseName, icon: Warehouse, color: 'text-primary' },
              { label: t('owner'), value: session.postedBy || common('system'), icon: User, color: 'text-emerald-500' },
              { label: t('items_count'), value: `${session.items.length} ${t('skus')}`, icon: ClipboardList, color: 'text-rose-500' },
              { label: t('last_updated'), value: session.updatedAt ? format(new Date(session.updatedAt), 'HH:mm') : common('dash'), icon: Clock, color: 'text-amber-500' },
            ].map((item, idx) => (
              <Card key={idx} className="p-5 bg-surface-container-lowest border-none shadow-sm flex flex-col gap-3 group transition-all rounded-lg relative overflow-hidden">
                <div className="flex items-center justify-between relative z-10">
                  <div className={cn("w-10 h-10 rounded-lg bg-current/10 flex items-center justify-center", item.color)}>
                    <item.icon className="w-5 h-5" />
                  </div>
                  <span className="text-label-xxs font-semibold text-muted-foreground/30 uppercase">{item.label}</span>
                </div>
                <div className="flex flex-col relative z-10">
                  <span className="text-title-sm font-semibold text-foreground line-clamp-1">{item.value}</span>
                </div>
              </Card>
            ))}
          </div>

          {/* Summary Table */}
          <Card className="bg-surface-container-lowest border-none shadow-sm rounded-lg overflow-hidden">
            <div className="p-6 border-b border-outline-variant/10 flex items-center justify-between">
              <div className="space-y-1">
                <h3 className="text-body-md font-semibold text-foreground">{t('inventory_manifest')}</h3>
                <p className="text-label-xs font-semibold text-muted-foreground/30 uppercase">{t('items_to_audit')}</p>
              </div>
            </div>
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow className="hover:bg-transparent border-none">
                    <TableHead className="text-label-xs font-semibold uppercase text-muted-foreground/40 h-12 px-6">{common('item')}</TableHead>
                    <TableHead className="text-label-xs font-semibold uppercase text-muted-foreground/40 text-center h-12">{t('snapshot_qty')}</TableHead>
                    <TableHead className="text-label-xs font-semibold uppercase text-muted-foreground/40 text-center h-12">{t('counted_qty')}</TableHead>
                    <TableHead className="text-label-xs font-semibold uppercase text-muted-foreground/40 text-center h-12">{t('variance')}</TableHead>
                    <TableHead className="text-label-xs font-semibold uppercase text-muted-foreground/40 text-end h-12 px-6">{common('status_label')}</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {session.items.map((item: any) => {
                    const hasCounted = item.countedQty !== undefined
                    const variance = item.variance ?? 0
                    const showSnapshot = !isCounting // Hide snapshot during counting for integrity
                    
                    return (
                      <TableRow key={item.id} className="hover:bg-surface-container-low/50 transition-colors border-none group">
                        <TableCell className="px-6 py-4">
                          <div className="flex flex-col gap-0.5">
                            <span className="font-bold text-body-md text-foreground group-hover:text-primary transition-colors">{item.itemName}</span>
                            <span className="text-label-xs font-medium text-muted-foreground/50 font-mono" dir="ltr">{item.barcode}</span>
                          </div>
                        </TableCell>
                        <TableCell className="text-center font-mono text-label-sm font-bold text-muted-foreground/60">
                          {showSnapshot ? `${item.snapshotQty} ${item.uom}` : common('dash')}
                        </TableCell>
                        <TableCell className="text-center font-mono text-label-sm font-bold text-foreground">
                          {hasCounted ? `${item.countedQty} ${item.uom}` : common('dash')}
                        </TableCell>
                        <TableCell className="text-center">
                          {showSnapshot && hasCounted ? (
                            <div className={cn(
                              "inline-flex items-center gap-1.5 px-2 py-0.5 rounded-md text-label-xs font-bold",
                              variance === 0 ? "bg-emerald-500/10 text-emerald-500" : 
                              variance > 0 ? "bg-blue-500/10 text-blue-500" : "bg-red-500/10 text-red-500"
                            )} dir="ltr">
                              {variance > 0 ? '+' : ''}{variance}
                            </div>
                          ) : common('dash')}
                        </TableCell>
                        <TableCell className="text-end px-6">
                          {hasCounted ? (
                            <Badge variant="outline" className="bg-emerald-500/10 text-emerald-500 border-none text-label-xxs font-semibold uppercase h-6">
                              {common('completed')}
                            </Badge>
                          ) : (
                            <Badge variant="outline" className="bg-surface-container-highest text-muted-foreground/60 border-none text-label-xxs font-semibold uppercase h-6">
                              {common('pending')}
                            </Badge>
                          )}
                        </TableCell>
                      </TableRow>
                    )
                  })}
                  {session.items.length === 0 && (
                    <TableRow className="hover:bg-transparent">
                      <TableCell colSpan={5} className="h-32 text-center text-muted-foreground/40 text-label-xs font-semibold uppercase italic">
                        {t('no_items_in_manifest')}
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </div>
          </Card>
          {/* Status Timeline */}
          <div className="bg-surface-container-lowest p-8 rounded-lg shadow-sm transition-all hover:bg-surface-container-low/50">
            <div className="flex items-center gap-3 mb-10">
              <History className="w-4 h-4 text-primary opacity-20" />
              <h3 className="text-label-xs font-semibold uppercase text-primary/30">{common('audit_trail') || 'Audit Trail'}</h3>
            </div>
            <StatusTimeline 
              entries={[
                { 
                  status: session.status.toLowerCase() as any, 
                  at: session.updatedAt || session.createdAt || new Date().toISOString(), 
                  by: session.postedBy || common('system') 
                }
              ]} 
            />
          </div>
        </div>
      </div>

      <FormFooter 
        onCancel={() => router.push('/stocktake')}
        isLocked={isLocked}
        isDirty={false}
      />
    </div>
  )
}

"use client"

import * as React from "react";
import { useStocktake, useUpdateItemCount, useCompleteCounting } from "@/features/operations/api/useStocktakes";
import { useWarehouses } from "@/features/warehouses/api/useWarehouses";
import { useTranslations } from "next-intl";
import { useDebouncedCallback } from "use-debounce";
import { useRouter } from "@/i18n/navigation";
import { Loader2 } from "lucide-react";
import { toast } from "sonner";
import { useUnsavedChangesGuard } from "@/lib/unsaved-changes/useUnsavedChangesGuard";
import { useVirtualizer } from "@tanstack/react-virtual";
import { mapToSessionVM, StocktakeItemVM } from "@/features/operations/mappers/stocktakeMapper";

import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { PageHeader } from "@/components/shared/PageHeader";
import { ScanInput } from "@/components/shared/ScanInput/ScanInput";
import { PermissionGate } from "@/components/shared/PermissionGate";
import { PostConfirmDialog } from "@/components/shared/PostConfirmDialog";
import { PageSkeleton } from "@/components/shared/PageSkeleton";
import { ErrorState } from "@/components/shared/ErrorState";
import { StatusBadge } from "@/components/shared/StatusBadge";

import { useAuth } from "@/providers/AuthProvider";
import { ActionGuard } from "@/core/workflow/ActionGuard";
import { type DocumentStatus } from "@/core/workflow/document-engine";
import { isStocktakeCounting } from "@/domain/status-guards";

export function StocktakeCountClient({ id, locale }: { id: string, locale: 'ar' | 'en' }) {
  const t = useTranslations('operations.stocktake')
  const common = useTranslations('common')
  const baseRouter = useRouter();
  const { user } = useAuth();
  const { router: guardedRouter } = useUnsavedChangesGuard(false);
  const { data: rawSession, isLoading: sessionLoading, error: sessionError } = useStocktake(id);
  const session = rawSession ? mapToSessionVM(rawSession) : null;
  const { data: warehouses, isLoading: isLoadingWarehouses, error: errorWarehouses } = useWarehouses();
  const updateCount = useUpdateItemCount();
  const completeCounting = useCompleteCounting();

  const [scanStatus, setScanStatus] = React.useState<"idle" | "success" | "error">("idle")
  const [statusMessage, setStatusMessage] = React.useState("")
  const [localCounts, setLocalCounts] = React.useState<Record<string, number>>({})
  const [focusedRowIndex, setFocusedRowIndex] = React.useState<number>(-1)
  
  const parentRef = React.useRef<HTMLDivElement>(null)
  const inputRefs = React.useRef<Map<number, HTMLInputElement>>(new Map())

  const items = session?.items || []

  const rowVirtualizer = useVirtualizer({
    count: items.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 88,
    overscan: 10,
  })

  // Synchronize focus when index changes
  React.useEffect(() => {
    if (focusedRowIndex !== -1) {
      rowVirtualizer.scrollToIndex(focusedRowIndex, { align: 'center' });
      // Small timeout to allow virtualization to render the row
      const timer = setTimeout(() => {
        const input = inputRefs.current.get(focusedRowIndex);
        if (input) {
          input.focus();
          input.select(); // Better UX for editing
        }
      }, 50);
      return () => clearTimeout(timer);
    }
  }, [focusedRowIndex, rowVirtualizer]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setFocusedRowIndex(prev => Math.min(prev + 1, items.length - 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setFocusedRowIndex(prev => Math.max(prev - 1, 0));
    } else if (e.key === 'Escape') {
      setFocusedRowIndex(-1);
      (document.activeElement as HTMLElement)?.blur();
    } else if (e.key === 'Enter') {
      // If we are in an input, move to next row
      if (e.target instanceof HTMLInputElement && e.target.type === 'number') {
        e.preventDefault();
        if (focusedRowIndex < items.length - 1) {
          setFocusedRowIndex(prev => prev + 1);
        } else {
          toast.info(t('last_item_reached'));
        }
      }
    }
  };

  const debouncedUpdate = useDebouncedCallback(
    (itemId: string, lineId: string, countedQty: number) => {
      updateCount.mutate({ stocktakeId: id, itemId, lineId, countedQty })
    },
    800
  )

  const isInitialized = React.useRef(false)
  React.useEffect(() => {
    if (session?.items && !isInitialized.current) {
      const counts: Record<string, number> = {}
      session.items.forEach((i) => {
        counts[i.id] = i.countedQty || 0
      })
      setLocalCounts(counts)
      isInitialized.current = true
    }
  }, [session?.items])

  if (sessionLoading || isLoadingWarehouses) return <PageSkeleton variant="list" />;
  if (sessionError || errorWarehouses || !session) return <ErrorState onRetry={() => window.location.reload()} />;
  
  const warehouse = warehouses?.find((w) => w.id === session.warehouseId);
  const warehouseName = warehouse ? (locale === 'ar' ? warehouse.nameAr : warehouse.nameEn) : (session.warehouseName || session.warehouseId);

  if (!isStocktakeCounting(session.status)) {
    baseRouter.replace(`/stocktake/${id}`);
    return null;
  }

  const handleScan = async (barcode: string) => {
    const index = items.findIndex((i) => i.barcode === barcode)
    if (index !== -1) {
      const item = items[index] as StocktakeItemVM
      const currentQty = localCounts[item.id] || 0
      const newQty = currentQty + 1
      
      setLocalCounts(prev => ({ ...prev, [item.id]: newQty }))
      updateCount.mutate({ stocktakeId: id, itemId: item.itemId, lineId: item.id, countedQty: newQty })
      
      setScanStatus("success")
      setStatusMessage(`${item.itemName}: ${newQty}`)
      
      // Focus the scanned row for immediate verification
      setFocusedRowIndex(index)

      setTimeout(() => {
        setScanStatus("idle")
        setStatusMessage("")
      }, 2000)
    } else {
      setScanStatus("error")
      setStatusMessage(t('no_item_found'))
      setTimeout(() => {
        setScanStatus("idle")
        setStatusMessage("")
      }, 3000)
    }
  }

  const handleFinish = () => {
    completeCounting.mutate(id, {
      onSuccess: () => {
        toast.success(t('posted_success'))
        guardedRouter.push(`/stocktake/${id}/variance`, { skipGuard: true })
      },
      onError: () => {
        toast.error(common('error'))
      }
    })
  }

  const hasCountedItems = session.items.some((i) => (localCounts[i.id] || 0) > 0)

  const virtualRows = rowVirtualizer.getVirtualItems();
  const totalSize = rowVirtualizer.getTotalSize();

  return (
    <PermissionGate action="edit" resource="operations_stocktake">
      <div className="space-y-6" onKeyDown={handleKeyDown}>
        <PageHeader
          title={session.sessionName}
          subtitle={warehouseName}
          backHref={`/stocktake/${id}`}
        >
          <div className="flex items-center gap-4">
            {updateCount.isPending && (
              <div className="flex items-center gap-2 text-label-sm text-muted-foreground animate-pulse">
                <Loader2 className="h-3 w-3 animate-spin" />
                {t('autosave_active')}
              </div>
            )}
            <StatusBadge 
              status={session.status} 
              className="px-4 py-1"
            />
            <ActionGuard 
              documentType="STOCKTAKE" 
              status={session.status as DocumentStatus} 
              action="SUBMIT" 
              role={user?.role || ''}
            >
              <PostConfirmDialog
                title={t('confirm_finish_title')}
                description={t('confirm_finish_desc')}
                onConfirm={handleFinish}
                trigger={
                  <Button disabled={!hasCountedItems || completeCounting.isPending}>
                    {t('finish_counting')}
                  </Button>
                }
              />
            </ActionGuard>
          </div>
        </PageHeader>

        <Card className="p-10 bg-surface-container-low border-none shadow-none rounded-[2.5rem]">
          <div className="max-w-md mx-auto mb-12">
            <ScanInput 
              onScan={handleScan}
              scanStatus={scanStatus}
              statusMessage={statusMessage}
              isScanning={updateCount.isPending}
              placeholder={t('scan_placeholder')}
              scannerMode={true}
            />
            <p className="text-center text-label-xs font-semibold text-muted-foreground/30 uppercase mt-3">
              {t('scan_mode')}
            </p>
          </div>

          <div 
            ref={parentRef}
            className="rounded-3xl bg-white/[0.01] overflow-auto h-[600px] relative"
          >
            <Table>
              <TableHeader className="bg-white/[0.02] sticky top-0 z-10 backdrop-blur-md">
                <TableRow className="hover:bg-transparent border-none">
                  <TableHead className="text-label-xs font-semibold uppercase text-muted-foreground/40 h-12 px-8 w-[40%]">{common('item')}</TableHead>
                  <TableHead className="text-label-xs font-semibold uppercase text-muted-foreground/40 h-12 w-[30%]">{common('lot')}</TableHead>
                  <TableHead className="text-label-xs font-semibold uppercase text-muted-foreground/40 text-center h-12 w-[150px]">{t('counted_qty')}</TableHead>
                  <TableHead className="text-label-xs font-semibold uppercase text-muted-foreground/40 text-end h-12 px-8 w-[100px]">{common('uom')}</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                <div style={{ height: `${totalSize}px`, width: '100%', position: 'relative' }}>
                  {virtualRows.map((virtualRow) => {
                    const item = items[virtualRow.index];
                    const isFocused = focusedRowIndex === virtualRow.index;

                    return (
                      <TableRow 
                        key={virtualRow.key} 
                        data-index={virtualRow.index}
                        ref={rowVirtualizer.measureElement}
                        className={cn(
                          "hover:bg-white/[0.01] transition-colors border-none group absolute top-0 left-0 w-full",
                          isFocused && "bg-primary/5 ring-1 ring-primary/20"
                        )}
                        style={{
                          height: `${virtualRow.size}px`,
                          transform: `translateY(${virtualRow.start}px)`,
                        }}
                      >
                        <TableCell className="px-8 py-6">
                          <div className="flex flex-col gap-1">
                            <span className="font-semibold text-foreground group-hover:text-primary transition-colors">{item.itemName}</span>
                            <span className="text-label-xs font-semibold text-muted-foreground/40 font-mono" dir="ltr">{item.barcode}</span>
                          </div>
                        </TableCell>
                        <TableCell>
                          <div className="flex flex-col gap-1">
                            <span className="text-body-md font-mono font-semibold text-muted-foreground/60" dir="ltr">{item.lotNumber}</span>
                            <span className="text-label-xs font-semibold text-muted-foreground/30 uppercase" dir="ltr">{item.expiryDate}</span>
                          </div>
                        </TableCell>
                        <TableCell>
                          <Input
                            ref={(el) => {
                              if (el) inputRefs.current.set(virtualRow.index, el);
                              else inputRefs.current.delete(virtualRow.index);
                            }}
                            type="number"
                            value={localCounts[item.id] ?? ''} 
                            onFocus={() => setFocusedRowIndex(virtualRow.index)}
                            onChange={(e) => {
                              const val = parseFloat(e.target.value) || 0
                              setLocalCounts(prev => ({ ...prev, [item.id]: val }))
                              debouncedUpdate(item.itemId, item.id, val)
                            }}
                            className={cn(
                              "text-center font-mono font-semibold h-10 bg-surface-container-medium border-none focus-visible:ring-1 transition-all rounded-lg",
                              isFocused ? "focus-visible:ring-primary" : "focus-visible:ring-primary/30"
                            )}
                            dir="ltr"
                          />
                        </TableCell>
                        <TableCell className="text-end px-8 font-semibold text-label-xs text-muted-foreground/40 uppercase">
                          {item.uom}
                        </TableCell>
                      </TableRow>
                    );
                  })}
                </div>
              </TableBody>
            </Table>
            {items.length === 0 && (
              <div className="h-32 flex items-center justify-center text-muted-foreground italic">
                {t('no_items_counted')}
              </div>
            )}
          </div>
        </Card>
      </div>
    </PermissionGate>
  )
}

