 </>
 )}
 </Button>
 </div>
 </div>
 </Card>
 </form>

 <PostConfirmDialog
 isOpen={confirmOpen}
 onOpenChange={setConfirmOpen}
 onConfirm={() => {
 setConfirmOpen(false);
 form.handleSubmit(onSubmit)();
 }}
 title={t('create_confirm_title')}
 description={t('create_confirm_desc')}
 confirmText={tc('confirm')}
 />
 </Form>
 </PermissionGate>
 );
}

'use client';

import { useState, useMemo } from 'react';
import { useRouter, Link } from '@/i18n/navigation';
import { useTranslations } from 'next-intl';
import { DataTable } from '@/components/shared/DataTable/DataTable';
import { ColumnDef } from '@tanstack/react-table';
import { useTransferList, TransferSummary } from '@/features/operations/hooks/useTransferList';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { MetricCard } from '@/components/ui/metric-card';
import { EmptyState } from '@/components/shared/EmptyState';
import { Button } from '@/components/ui/button';
import { Plus, Filter, Repeat, Truck, CheckCircle } from 'lucide-react';
import { format } from 'date-fns';
import { PageHeader } from '@/components/shared/PageHeader';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Input } from '@/components/ui/input';
import { StatusBadge } from '@/components/shared/StatusBadge';
import { isTransferInTransit, isTransferPosted } from '@/domain/status-guards';
import { TRANSFER_STATUS_UI, getStatusConfig } from '@/domain/status-ui-map';
import { TRANSFER_STATUS } from '@/contracts/statuses';

export function TransferListClient() {
 const t = useTranslations('operations.transfer');
 const tCommon = useTranslations('common');
 const router = useRouter();
 
 const [page, setPage] = useState(1);
 const [status, setStatus] = useState<string>('');

 const { data, isLoading } = useTransferList({ status, page });

 const columns = useMemo<ColumnDef<TransferSummary>[]>(() => [
 {
 accessorKey: 'transfer_status',
 header: tCommon('status_label'),
 cell: ({ row }) => <StatusBadge status={row.original.transfer_status} />,
 },
 {
 accessorKey: 'document_number',
 header: tCommon('doc_number'),
 cell: ({ row }) => (
 <span dir="ltr" className="font-mono text-cyan-500/90 font-semibold text-body-md">
 {row.original.document_number}
 </span>
 ),
 },
 {
 accessorKey: 'from_warehouse_id',
 header: t('from_warehouse'),
 cell: ({ row }) => (
 <span className="opacity-80 font-medium">
 {tCommon('warehouses.' + row.original.from_warehouse_id.toLowerCase())}
 </span>
 ),
 },
 {
 accessorKey: 'to_warehouse_id',
 header: t('to_warehouse'),
 cell: ({ row }) => (
 <span className="opacity-80 font-medium">
 {tCommon('warehouses.' + row.original.to_warehouse_id.toLowerCase())}
 </span>
 ),
 },
 {
 accessorKey: 'shipped_at',
 header: t('shipped_at'),
 cell: ({ row }) =>
 row.original.shipped_at ? (
 <span dir="ltr" className="text-label-xs opacity-60 font-mono font-medium">{format(new Date(row.original.shipped_at), 'dd/MM/yyyy')}</span>
 ) : <span className="opacity-20">ظ¤</span>,
 },
 {
 accessorKey: 'created_at',
 header: tCommon('created_at'),
 cell: ({ row }) =>
 row.original.created_at ? (
 <span dir="ltr" className="text-label-xs opacity-60 font-mono font-medium">
 {format(new Date(row.original.created_at), 'dd/MM/yyyy')}
 </span>
 ) : <span className="opacity-20">ظ¤</span>,
 },
 {
 id: 'actions',
 header: '',
 cell: ({ row }) => (
 <div className="flex justify-end">
 <Button 
 variant="ghost" 
 size="sm" 
 className="text-label-xs font-semibold uppercase text-cyan-500 hover:text-cyan-500 hover:bg-cyan-500/10 h-7"
 onClick={(e) => {
 e.stopPropagation();
 router.push(`/transfers/${row.original.id}`);
 }}
 >
 {tCommon('view') || 'Inspect'}
 </Button>
 </div>
 ),
 },
 ], [t, tCommon, router]);

  const totalTransfersCount = data?.meta?.total || 0;
  const inTransitCount = data?.data?.filter(i => isTransferInTransit(i.transfer_status)).length || 0;
  const completedCount = data?.data?.filter(i => isTransferPosted(i.transfer_status)).length || 0;

  return (
    <div className="p-8 max-w-[1600px] mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-1000">
      <Breadcrumb 
        items={[
          { label: tCommon('modules.operations'), href: `/transfers` },
          { label: t('title') }
        ]} 
      />

      <PageHeader 
        title={t('title')} 
        description={t('description')}
        actions={
          <div className="flex items-center gap-6">
            <div className="flex flex-col items-end gap-1 border-e border-outline-low pe-6 hidden md:flex">
              <div className="text-label-xs font-semibold uppercase text-muted-foreground/60 flex items-center gap-2">
                <span className="w-1.5 h-1.5 rounded-full bg-cyan-500 animate-pulse shadow-[0_0_8px_rgba(0,229,255,0.8)]" />
                {tCommon('status.live_updates')}
              </div>
              <div className="text-label-xxs font-semibold text-muted-foreground/40" dir="ltr">
                {tCommon('status.last_sync')}: {new Date().toLocaleTimeString()}
              </div>
            </div>
            <PermissionGate action="create" resource="transfer">
              <Link href="/transfers/new">
                <Button className="h-11 px-8 bg-cyan-600 hover:bg-cyan-500 text-white text-label-xs font-semibold uppercase rounded-md transition-all shadow-lg shadow-cyan-900/10">
                  <Plus className="w-3.5 h-3.5 me-2" />
                  {t('create_new')}
                </Button>
              </Link>
            </PermissionGate>
          </div>
        }
      />

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <MetricCard
          label={t('total_transfers')}
          value={totalTransfersCount}
          icon={Repeat}
          trend="active"
        />
        <MetricCard
          label={tCommon('status.in_transit')}
          value={inTransitCount}
          icon={Truck}
          trend="active"
          color="amber"
        />
        <MetricCard
          label={t('completed')}
          value={completedCount}
          icon={CheckCircle}
          trend="active"
          color="emerald"
        />
      </div>

      <div className="bg-surface-container-lowest rounded-lg border border-outline-low/5 overflow-hidden shadow-sm">
        <DataTable 
          columns={columns}
          data={data?.data || []}
          isLoading={isLoading}
          onRowClick={(row: TransferSummary) => router.push(`/transfers/${row.id}`)}
          collectionName="operations_transfers"
          enableVirtualization={true}
          containerHeight="600px"
          emptyState={
            <EmptyState 
              title={t('no_records')} description={t('description')} action={
                <PermissionGate action="create" resource="transfer">
                  <Button 
                    onClick={() => router.push(`/transfers/new`)}
                    className="bg-cyan-500/10 hover:bg-cyan-500/20 text-cyan-500 border border-cyan-500/20 rounded-md"
                  >
                    <Plus className="w-4 h-4 me-2" />
                    {t('create_new')}
                  </Button>
                </PermissionGate>
              }
            />
          }
          pagination={data?.meta ? {
            page: page,
            pageSize: 10,
            total: data.meta.total,
            totalPages: data.meta.total_pages,
            onPageChange: setPage
          } : undefined}
          filters={
            <div className="flex flex-wrap items-end gap-6 w-full py-6 px-8 bg-surface-container-low border border-outline-low/5 rounded-lg shadow-sm">
              <div className="flex flex-col gap-2 min-w-[240px] flex-1">
                <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ms-1">{tCommon('status_label')}</label>
                <Select
                  value={status || 'ALL'} onValueChange={(val) => { setStatus(val === 'ALL' ? '' : (val ?? '')); setPage(1); }}
                >
                  <SelectTrigger className="w-full bg-surface-container-highest/40 border-none h-12 px-4 text-label-sm font-semibold rounded-md transition-all hover:bg-surface-container-highest/60 focus:ring-1 focus:ring-cyan-500/10">
                    <SelectValue placeholder={tCommon('status.all')} />
                  </SelectTrigger>
                  <SelectContent className="bg-surface-container-highest border-outline-low/10 rounded-md">
                    <SelectItem value="ALL">{tCommon('status.all')}</SelectItem>
                    {Object.entries(TRANSFER_STATUS).map(([key, value]) => (
                      <SelectItem key={value} value={value}>
                        {tCommon(getStatusConfig(value).labelKey)}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

 <div className="flex flex-col gap-2 min-w-[300px] flex-[2]">
 <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ms-1">{tCommon('search')}</label>
 <div className="relative group">
 <Input
 placeholder={t('search_placeholder')}
 className="w-full bg-surface-container-highest/40 border-none h-12 ps-12 pe-4 text-label-sm font-semibold rounded-md transition-all group-hover:bg-surface-container-highest/60 focus:ring-1 focus:ring-cyan-500/10"
 />
 <svg className="absolute start-4 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground/40 transition-colors group-hover:text-cyan-500/60" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
 </div>
 </div>

 <Button className="h-12 px-8 bg-surface-container-highest/60 hover:bg-cyan-500 hover:text-black text-foreground text-label-xs font-semibold uppercase rounded-md transition-all border border-outline-low/5 shadow-sm group">
 <Filter className="w-3.5 h-3.5 me-2 transition-transform group-hover:rotate-180" />
 {tCommon('filters')}
 </Button>
 </div>
 }
 />
 </div>
 </div>
 );
}

"use client";

import { useTranslations } from 'next-intl';
import { useTransfer } from '@/features/operations/hooks/useTransfer';
import { isDocumentLocked, type DocumentStatus } from '@/core/workflow/document-engine';
import { TransferForm } from '@/features/operations/components/transfer-form';
import { TransferViewer } from '@/features/operations/components/transfer-viewer';
import { TRANSFER_STATUS } from '@/contracts/statuses';

import { useConflictHandler } from '@/core/concurrency/useConflictHandler';
import { ConflictDialog } from '@/core/concurrency/ConflictDialog';

import { PageSkeleton } from '@/components/shared/PageSkeleton';

export function TransferDetailClient({ id }: { id: string }) {
  const t = useTranslations('operations.transfer');
  const { data: transfer, isLoading } = useTransfer(id);
  const conflict = useConflictHandler('transfer', id);

  if (isLoading) return <PageSkeleton variant="detail" />;

  const transferStatus = transfer?.transfer_status ?? TRANSFER_STATUS.DRAFT;
  const isDocLocked = isDocumentLocked("TRANSFER", transferStatus as DocumentStatus);

  if (isDocLocked && transfer) {
    return <TransferViewer transfer={transfer} />;
  }

  return (
    <>
      <TransferForm 
        transfer={transfer} 
        id={id} 
        onConflict={conflict.triggerConflict}
      />
      <ConflictDialog 
        open={conflict.open}
        onClose={conflict.handleClose}
        onReload={conflict.handleReload}
      />
    </>
  );
}

'use client';

import { useTranslations } from 'next-intl';
import { useRouter } from '@/i18n/navigation';
import { PageHeader } from '@/components/shared/PageHeader';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { Button } from '@/components/ui/button';
import { StatusBadge, type BadgeStatus } from '@/components/shared/StatusBadge';
import { DocumentLineItemTable } from '@/components/shared/DocumentLineItemTable/DocumentLineItemTable';
import { Truck, PackageCheck, Printer, ArrowLeft } from 'lucide-react';
import { format } from 'date-fns';
import { TransferLine } from '@/features/operations/hooks/useTransfer';
import { TRANSFER_STATUS } from '@/contracts/statuses';

interface TransferViewerProps {
  transfer: any;
  locale: 'ar' | 'en';
}

export function TransferViewer({ transfer, locale }: TransferViewerProps) {
  const t = useTranslations('operations.transfer');
  const tCommon = useTranslations('common');
  const router = useRouter();

  const transferStatus = transfer?.transfer_status ?? TRANSFER_STATUS.DRAFT;

  return (
    <div className="p-8 max-w-[1600px] mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-1000">
      <div className="flex items-center justify-between">
        <Breadcrumb 
          items={[
            { label: tCommon('modules.operations'), href: `/transfers` },
            { label: t('title'), href: `/transfers` },
            { label: t('detail_title') }
          ]} 
        />
        <Button
          variant="ghost"
          onClick={() => router.back()}
          className="text-label-xs font-semibold uppercase text-muted-foreground hover:text-foreground transition-colors"
        >
          <ArrowLeft className="w-3 h-3 me-2" />
          {tCommon('back')}
        </Button>
      </div>

      <PageHeader
        title={t('detail_title')}
        description={
          <div className="flex items-center gap-2">
            <span>{tCommon('doc_number')}</span>
            <span dir="ltr" className="font-mono text-cyan-500/80">{transfer?.document_number}</span>
          </div>
        }
        actions={
          <div className="flex gap-4 items-center">
            <StatusBadge status={transferStatus as BadgeStatus} />
            
            <Button
              variant="outline"
              className="bg-surface-container-high border-white/5 rounded-xl h-11 px-6 text-label-xs font-semibold uppercase transition-all hover:bg-surface-container-highest"
              onClick={() => window.print()}
            >
              <Printer className="w-4 h-4 me-2" />
              {tCommon('print')}
            </Button>
          </div>
        }
      />

      <div className="grid grid-cols-1 md:grid-cols-4 gap-8 bg-surface-container-low/50 p-8 rounded-2xl border border-white/5 relative overflow-hidden shadow-2xl">
        <div className="absolute top-0 inset-x-0 h-1 bg-gradient-to-e from-cyan-500/50 via-cyan-500/20 to-transparent" />

        <div className="space-y-2">
          <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ms-1">{t('from_warehouse')}</label>
          <div className="bg-surface-container-highest/40 border border-white/5 rounded-xl p-4 font-bold text-body-md">
            {transfer?.from_warehouse_name}
          </div>
        </div>

        <div className="space-y-2">
          <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ms-1">{t('to_warehouse')}</label>
          <div className="bg-surface-container-highest/40 border border-white/5 rounded-xl p-4 font-bold text-body-md">
            {transfer?.to_warehouse_name}
          </div>
        </div>

        {transfer?.shipped_at && (
          <div className="space-y-2">
            <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ms-1">{t('shipped_at')}</label>
            <div className="bg-surface-container-highest/30 border border-white/5 rounded-xl p-4 flex items-center justify-between">
              <span dir="ltr" className="font-mono text-body-md font-bold text-cyan-500/80">
                {format(new Date(transfer.shipped_at), 'MMM dd, yyyy HH:mm')}
              </span>
              <Truck className="w-4 h-4 text-cyan-500/40" />
            </div>
          </div>
        )}

        {transfer?.received_at && (
          <div className="space-y-2">
            <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ms-1">{t('received_at')}</label>
            <div className="bg-surface-container-highest/30 border border-white/5 rounded-xl p-4 flex items-center justify-between">
              <span dir="ltr" className="font-mono text-body-md font-bold text-emerald-500/80">
                {format(new Date(transfer.received_at), 'MMM dd, yyyy HH:mm')}
              </span>
              <PackageCheck className="w-4 h-4 text-emerald-500/40" />
            </div>
          </div>
        )}

        <div className="col-span-1 md:col-span-4 space-y-2">
          <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ms-1">{tCommon('notes')}</label>
          <div className="bg-surface-container-highest/40 border border-white/5 rounded-xl p-4 font-medium text-body-md min-h-[60px]">
            {transfer?.notes || 'ظ¤'}
          </div>
        </div>

        {transfer?.variance_reason && (
          <div className="col-span-1 md:col-span-4 space-y-2">
            <label className="text-label-xs font-semibold uppercase text-status-warning/80 ms-1">{t('variance_reason')}</label>
            <div className="bg-status-warning/5 border border-status-warning/20 rounded-xl p-4 font-medium text-body-md">
              {transfer.variance_reason}
            </div>
          </div>
        )}
      </div>

      <div className="bg-surface-container-low/30 rounded-2xl border border-white/5 overflow-hidden shadow-2xl">
        <DocumentLineItemTable
          lines={transfer?.lines ?? []}
          locale={locale as 'ar' | 'en'} 
          isReadOnly={true}
          onRemoveLine={() => {}}
          hideLotColumns={true}
          headers={{
            code: tCommon('table_headers.code'),
            name: tCommon('table_headers.name'),
            qty: t('transfer_qty'),
            uom: tCommon('table_headers.uom'),
          }}
          extraColumns={[
            {
              header: t('shipped_qty'),
              cell: (line: TransferLine) => (
                <div className="flex justify-center">
                  <span dir="ltr" className="font-mono text-body-md font-semibold bg-surface-container-highest px-3 py-1 rounded-lg border border-white/5">
                    {line.shipped_qty ?? line.qty}
                  </span>
                </div>
              ),
            },
            {
              header: t('received_qty'),
              cell: (line: TransferLine) => (
                <div className="flex justify-center">
                  <span dir="ltr" className={`font-mono text-body-md font-semibold px-3 py-1 rounded-lg border border-white/5 ${line.received_qty ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' : 'bg-surface-container-highest text-muted-foreground/40'}`}>
                    {line.received_qty ?? 'ظ¤'}
                  </span>
                </div>
              ),
            },
          ]}
        />
      </div>
    </div>
  );
}

'use client';

