'use client';

import { useState, useMemo, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { useRouter } from '@/i18n/navigation';
import { useQueryClient } from '@tanstack/react-query';
import { PageHeader } from '@/components/shared/PageHeader';
import { Button } from '@/components/ui/button';
import { PostConfirmDialog } from '@/components/shared/PostConfirmDialog';
import { useToast } from '@/hooks/use-toast';
import { useGRN, type GRNDetail } from '@/features/purchasing/hooks/useGRN';
import { useAuth } from '@/providers/AuthProvider';
import { canPerformActionV2, isDocumentLocked, type DocumentStatus } from '@/core/workflow/document-engine';
import { useCurrencies } from '@/features/purchasing/hooks/useCurrencies';
import { useFXRates } from '@/features/purchasing/hooks/useFXRates';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { AlertCircle, TrendingUp, ShieldCheck, Wallet, ArrowRightLeft } from 'lucide-react';
import { cn } from '@/lib/utils';
import { useForm } from 'react-hook-form';
import { useUnsavedChangesGuard } from '@/lib/unsaved-changes/useUnsavedChangesGuard';
import { usePostGRN } from '@/features/purchasing/hooks/usePostGRN';
import { PageSkeleton } from '@/components/shared/PageSkeleton';
import { ErrorState } from '@/components/shared/ErrorState';

interface GRNPostClientProps {
 id: string;
 locale: 'ar' | 'en';
}

export function GRNPostClient({ id, locale }: GRNPostClientProps) {
 const t = useTranslations('procurement.grn');
 const tc = useTranslations('common');
 const router = useRouter();
 const queryClient = useQueryClient();
 const { user } = useAuth();
 
 const { toast } = useToast();
 
 const { data: grn, isLoading: isLoadingGRN } = useGRN(id);
 const { data: currencies } = useCurrencies();
 
  const form = useForm({
    defaultValues: {
      fx_rate: 1
    }
  });

  const fxRate = form.watch('fx_rate');
  const { guardedRouter } = useUnsavedChangesGuard(form.formState.isDirty);
  const postMutation = usePostGRN(id);

  const baseCurrency = currencies?.find(c => c.is_base)?.code || 'SAR';
  const supplierCurrency = grn?.currency_id || 'SAR';

  // Live FX conversion logic for display
  const { data: fxRates } = useFXRates(supplierCurrency, baseCurrency);
  
  useEffect(() => {
    if (fxRates?.[0]?.rate && !form.formState.isDirty) {
      form.reset({ fx_rate: fxRates[0].rate });
    }
  }, [fxRates, form]);

 const totalSupplier = useMemo(() => {
 return grn?.lines.reduce((acc, line) => acc + (line.received_qty * (line.unit_cost_foreign || 0)), 0) || 0;
 }, [grn]);

 const totalBase = useMemo(() => {
 return totalSupplier * fxRate;
 }, [totalSupplier, fxRate]);

 // Expected rate from PO or master data (for comparison)
 const expectedRate = grn?.po_fx_rate || fxRates?.[0]?.rate || 1;
 const rateVariance = ((fxRate - expectedRate) / expectedRate) * 100;

 // Enforce role and workflow status (PART 1)
 const canPost = useMemo(() => {
 if (!grn || !user) return false;
 return canPerformActionV2('GRN', grn.status as DocumentStatus, 'POST', user.role);
 }, [grn, user]);

 useEffect(() => {
 if (grn && !isLoadingGRN) {
 // If already posted, redirect
 if (isDocumentLocked('GRN', grn.status as DocumentStatus)) {
 router.replace(`/goods-received/${id}`);
 return;
 }
 
 // Strict enforcement: only documents allowed by the engine can be posted
 if (!canPerformActionV2('GRN', grn.status as DocumentStatus, 'POST', user?.role)) {
 router.replace(`/goods-received/${id}`);
 }
 }
 }, [grn, isLoadingGRN, id, router, canPost, user]);

  const [isPostDialogOpen, setIsPostDialogOpen] = useState(false);

  const handlePost = () => {
    postMutation.mutate({
      fx_rate: fxRate,
      confirmation: 'ACKNOWLEDGE_IRREVERSIBLE',
      version: grn?.version || 1
    }, {
      onSuccess: () => {
        toast.success(t('posted_success'));
        setIsPostDialogOpen(false);
        guardedRouter.push(`/goods-received/${id}`, { skipGuard: true });
      }
    });
  };

  if (isLoadingGRN) {
    return <PageSkeleton />;
  }

  if (!grn) {
    return <ErrorState message={tc('not_found')} onRetry={() => queryClient.invalidateQueries({ queryKey: ['grn', id] })} />;
  }

 if (!canPost) {
 return (
 <div className="flex flex-col items-center justify-center h-[60vh] gap-4">
 <AlertCircle className="w-12 h-12 text-destructive opacity-50" />
 <p className="text-body-md font-bold uppercase text-muted-foreground">{tc('permission_denied')}</p>
 </div>
 );
 }

 return (
 <div className="flex flex-col gap-10 pb-20">
 <PageHeader
 title={`#${grn.document_number}`}
 description={t('fx_capture_title')}
 showStatus
 status={grn.status}
 actions={
 <div className="flex items-center gap-4">
 <Button variant="ghost" onClick={() => router.back()} className="rounded-2xl">
 {tc('cancel')}
 </Button>
          <PostConfirmDialog
            open={isPostDialogOpen}
            onOpenChange={setIsPostDialogOpen}
            title={t('post_confirm_title')}
            description={t('post_confirm_desc')}
            warningText={t('post_irreversible')}
            requiresTextConfirmation={true}
            onConfirm={handlePost}
            isLoading={postMutation.isPending}
            confirmKeyword={t('confirm_keyword')}
          >
            <Button 
              disabled={postMutation.isPending || fxRate <= 0 || grn.lines.length === 0}
              className="h-12 px-10 bg-primary hover:bg-primary/90 text-primary-foreground text-label-xs font-semibold uppercase shadow-lg shadow-primary/20 rounded-2xl"
            >
              {t('post_grn')}
            </Button>
          </PostConfirmDialog>
 </div>
 }
 />

 <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
 {/* FX Panel (PART 2) */}
 <div className="lg:col-span-2 space-y-8">
 <div className="bg-surface-container-low p-10 rounded-[32px] border border-white/5 shadow-2xl relative overflow-hidden group">
 <div className="absolute top-0 end-0 p-8 opacity-[0.03] group-hover:opacity-[0.1] transition-all duration-700">
 <TrendingUp className="w-40 h-40" />
 </div>

 <div className="relative z-10 space-y-10">
 <div className="flex items-center gap-4">
 <div className="w-10 h-10 bg-primary/10 rounded-2xl flex items-center justify-center">
 <ArrowRightLeft className="w-5 h-5 text-primary" />
 </div>
 <h3 className="text-label-xs font-semibold uppercase text-primary">{t('fx_capture_title')}</h3>
 </div>

 <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
 <div className="space-y-4">
 <Label className="text-label-xs font-semibold uppercase text-muted-foreground/60">{tc('order_currency')}</Label>
 <div className="bg-surface-container-highest h-16 rounded-2xl flex items-center px-6 border border-white/5">
 <span className="font-mono font-semibold text-title-lg text-foreground/40">{supplierCurrency}</span>
 </div>
 </div>

 <div className="space-y-4">
 <Label className="text-label-xs font-semibold uppercase text-muted-foreground/60">{tc('base_currency')}</Label>
 <div className="bg-surface-container-highest h-16 rounded-2xl flex items-center px-6 border border-white/5">
 <span className="font-mono font-semibold text-title-lg text-foreground/40">{baseCurrency}</span>
 </div>
 </div>

 <div className="space-y-4">
 <Label className="text-label-xs font-semibold uppercase text-primary/80">{t('fx_capture_title')}</Label>
 <div className="relative group">
                <Input 
                  type="number"
                  step="0.0001"
                  dir="ltr"
                  className="h-16 bg-surface-container-highest rounded-2xl border-white/10 focus:border-primary/50 text-headline-lg font-mono font-semibold"
                  {...form.register('fx_rate', { valueAsNumber: true })}
                />
 <div className="absolute inset-y-0 end-4 flex items-center">
 <TrendingUp className="w-5 h-5 text-primary/40 group-focus-within:text-primary transition-colors" />
 </div>
 </div>
 </div>

 <div className="flex flex-col justify-end pb-2">
 <div className="flex items-center gap-2">
 <div className={cn(
 "w-2 h-2 rounded-full animate-pulse",
 Math.abs(rateVariance) > 5 ? "bg-destructive" : "bg-primary"
 )} />
 <p className="text-label-xs font-semibold uppercase text-muted-foreground/40 italic">
 * {tc('confirm_rate')}
 </p>
 </div>
 </div>
 </div>
 </div>
 </div>

 {/* Immutability Warning */}
 <div className="bg-amber-500/5 border border-amber-500/20 p-8 rounded-[28px] flex gap-6 items-start">
 <div className="w-12 h-12 bg-amber-500/10 rounded-2xl flex items-center justify-center shrink-0">
 <ShieldCheck className="w-6 h-6 text-amber-500" />
 </div>
 <div className="space-y-2">
 <h4 className="text-label-xs font-semibold uppercase text-amber-500">{t('fx_freeze_title')}</h4>
 <p className="text-body-md text-amber-200/60 leading-relaxed font-medium">{t('fx_freeze_desc')}</p>
 </div>
 </div>
 </div>

 {/* Sidebar Summary (PART 3) */}
 <div className="space-y-6">
 <div className="bg-surface-container-high p-8 rounded-[32px] shadow-2xl border border-white/10 space-y-8">
 <div className="flex items-center justify-between">
 <div className="space-y-2">
 <p className="text-label-xs font-semibold uppercase text-muted-foreground/50">{tc('supplier')}</p>
 <h2 className="text-title-lg font-bold">{grn.supplier?.name || 'Supply Co'}</h2>
 </div>
 <div className="w-12 h-12 bg-white/5 rounded-2xl flex items-center justify-center">
 <Wallet className="w-6 h-6 text-muted-foreground/40" />
 </div>
 </div>

 <div className="h-px bg-white/5" />

 <div className="space-y-6">
 <div className="flex justify-between items-center">
 <p className="text-label-xs font-semibold uppercase text-muted-foreground/50">{tc('total')} ({supplierCurrency})</p>
 <p dir="ltr" className="font-mono font-semibold text-title-sm">{totalSupplier.toLocaleString(undefined, { minimumFractionDigits: 2 })}</p>
 </div>
 
 <div className="space-y-3 bg-surface-container-highest/50 p-6 rounded-2xl border border-white/5">
 <div className="flex justify-between items-center opacity-60">
 <p className="text-label-xxs font-bold uppercase">Market Rate</p>
 <p dir="ltr" className="font-mono text-label-sm">{expectedRate.toFixed(4)}</p>
 </div>
 <div className="flex justify-between items-center">
 <p className="text-label-xxs font-bold uppercase">Rate Variance</p>
 <p dir="ltr" className={cn(
 "font-mono text-label-sm font-semibold",
 rateVariance > 0 ? "text-emerald-400" : rateVariance < 0 ? "text-destructive" : "text-muted-foreground"
 )}>
 {rateVariance > 0 ? '+' : ''}{rateVariance.toFixed(2)}%
 </p>
 </div>
 </div>

 <div className="flex justify-between items-center bg-primary/5 p-6 rounded-2xl border border-primary/10 relative overflow-hidden group">
 <div className="absolute inset-0 bg-primary/5 translate-y-full group-hover:translate-y-0 transition-transform duration-500" />
 <div className="relative z-10 flex flex-col gap-1">
 <p className="text-label-xs font-semibold uppercase text-primary/60">{tc('base_currency')}</p>
 <p dir="ltr" className="font-mono font-semibold text-headline-lg text-primary">{totalBase.toLocaleString(undefined, { minimumFractionDigits: 2 })}</p>
 </div>
 </div>
 </div>

 <div className="space-y-2 pt-4">
 <p className="text-label-xs font-semibold uppercase text-muted-foreground/30 text-center leading-relaxed">
 {tc('posting_irreversible')}
 </p>
 </div>
 </div>
 </div>
 </div>
 </div>
 );
}

"use client"

import * as React from "react"
import { useTranslations } from "next-intl"
import { useForm } from "react-hook-form"
import { zodResolver } from "@hookform/resolvers/zod"
import { z } from "zod"
import { Calendar as CalendarIcon, Loader2 } from "lucide-react"
import { format } from "date-fns"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import {
 Dialog,
 DialogContent,
 DialogDescription,
 DialogFooter,
 DialogHeader,
 DialogTitle,
} from "@/components/ui/dialog"
import {
 Form,
 FormControl,
 FormField,
 FormItem,
 FormLabel,
 FormMessage,
} from "@/components/ui/form"
import { Input } from "@/components/ui/input"
import { Calendar } from "@/components/ui/calendar"
import {
 Popover,
 PopoverContent,
 PopoverTrigger,
} from "@/components/ui/popover"

const lotFormSchema = z.object({
 lotNumber: z.string().min(1, "lot_required"),
 expiryDate: z.date({
 message: "expiry_required",
 }),
 receivedQuantity: z.number().min(0.01, "qty_greater_than_zero"),
})

export type LotFormValues = z.infer<typeof lotFormSchema>

interface LotEntryModalProps {
 isOpen: boolean
 onClose: () => void
 onConfirm: (values: LotFormValues) => void
 itemName: string
 itemBarcode: string
 isSubmitting?: boolean
}

export function LotEntryModal({
 isOpen,
 onClose,
 onConfirm,
 itemName,
 itemBarcode,
 isSubmitting = false,
}: LotEntryModalProps) {
 const t = useTranslations("procurement.grn")
 const common = useTranslations("common")

 const localizedSchema = React.useMemo(() => z.object({
 lotNumber: z.string().min(1, t("lot_required")),
 expiryDate: z.date({
 message: t("expiry_required"),
 }),
 receivedQuantity: z.number().min(0.01, t("qty_greater_than_zero")),
 }), [t])

 const form = useForm<LotFormValues>({
 resolver: zodResolver(localizedSchema),
 defaultValues: {
 lotNumber: "",
 receivedQuantity: 1,
 },
 })

 // Reset form when modal opens with new item
 React.useEffect(() => {
 if (isOpen) {
 form.reset({
 lotNumber: "",
 receivedQuantity: 1,
 })
 }
 }, [isOpen, form])

 const onSubmit = (values: LotFormValues) => {
 onConfirm(values)
 }

 return (
 <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
 <DialogContent className="sm:max-w-[425px] bg-surface-container-high border-none rounded-[2rem] shadow-2xl p-8">
 <DialogHeader>
 <DialogTitle className="text-title-lg font-semibold">{t("lot_entry_title")}</DialogTitle>
 <DialogDescription className="text-muted-foreground/60">
 {t("lot_entry_sub")}
 </DialogDescription>
 </DialogHeader>

 <div className="py-4 space-y-4">
 <div className="p-4 rounded-2xl bg-primary/5 flex flex-col gap-1 border border-primary/10">
 <span className="text-label-sm font-semibold text-primary/60 uppercase">{common("item")}</span>
 <span className="font-semibold text-foreground">{itemName}</span>
 <span className="text-label-xs font-mono text-muted-foreground/40" dir="ltr">{itemBarcode}</span>
 </div>

 <Form {...form}>
 <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
 <FormField
 control={form.control}
 name="lotNumber"
 render={({ field }) => (
 <FormItem>
 <FormLabel className="text-label-xs font-semibold uppercase text-muted-foreground/60">{t("lot_number")}</FormLabel>
 <FormControl>
 <Input 
 placeholder="e.g. LOT-2024-001" 
 {...field} 
 className="bg-surface-container-medium border-none h-12 rounded-xl font-semibold focus-visible:ring-1 focus-visible:ring-primary/30"
 />
 </FormControl>
 <FormMessage className="text-label-xs font-semibold" />
 </FormItem>
 )}
 />

 <div className="grid grid-cols-2 gap-4">
 <FormField
 control={form.control}
 name="expiryDate"
 render={({ field }) => (
 <FormItem className="flex flex-col">
 <FormLabel className="text-label-xs font-semibold uppercase text-muted-foreground/60">{t("expiry_date")}</FormLabel>
 <Popover>
 <PopoverTrigger asChild>
 <FormControl>
 <Button
 variant={"outline"} className={cn(
 "w-full pl-3 text-left font-semibold h-12 bg-surface-container-medium border-none rounded-xl hover:bg-surface-container-highest transition-colors",
 !field.value && "text-muted-foreground"
 )}
 >
 {field.value ? (
 format(field.value, "PPP")
 ) : (
 <span>{common("select_date")}</span>
 )}
 <CalendarIcon className="ml-auto h-4 w-4 opacity-50" />
 </Button>
 </FormControl>
 </PopoverTrigger>
 <PopoverContent className="w-auto p-0 border-none shadow-2xl rounded-2xl" align="start">
 <Calendar
 mode="single"
 selected={field.value}
 onSelect={(date: Date | undefined) => field.onChange(date)}
 disabled={(date: Date) =>
 date < new Date(new Date().setHours(0, 0, 0, 0))
 }
 initialFocus
 className="bg-surface-container-high"
 />
 </PopoverContent>
 </Popover>
 <FormMessage className="text-label-xs font-semibold" />
 </FormItem>
 )}
 />

 <FormField
 control={form.control}
 name="receivedQuantity"
 render={({ field }) => (
 <FormItem>
 <FormLabel className="text-label-xs font-semibold uppercase text-muted-foreground/60">{t("receiving_qty")}</FormLabel>
 <FormControl>
 <Input 
 type="number" 
 step="0.01"
 {...field}
 onChange={e => field.onChange(parseFloat(e.target.value) || 0)}
 className="bg-surface-container-medium border-none h-12 rounded-xl font-semibold font-mono focus-visible:ring-1 focus-visible:ring-primary/30"
 dir="ltr"
 />
 </FormControl>
 <FormMessage className="text-label-xs font-semibold" />
 </FormItem>
 )}
 />
 </div>

 <DialogFooter className="pt-4">
 <Button 
 type="button" 
 variant="ghost" 
 onClick={onClose}
 className="rounded-xl font-semibold text-label-xs uppercase"
 >
 {common("cancel")}
 </Button>
 <Button 
 type="submit" 
 disabled={isSubmitting}
 className="rounded-xl font-semibold text-label-xs uppercase min-w-[120px]"
 >
 {isSubmitting ? <Loader2 className="h-4 w-4 animate-spin" /> : t("confirm_lot")}
 </Button>
 </DialogFooter>
 </form>
 </Form>
 </div>
 </DialogContent>
 </Dialog>
 )
}

"use client";
import { useForm, useFieldArray, useWatch } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { useSearchParams } from 'next/navigation';
import { useRouter } from '@/i18n/navigation';;
import { useEffect } from "react";
import { useTranslations } from "next-intl";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { LockBanner } from "@/components/ui/lock-banner";
import { Save, Receipt, Search, Plus, Trash2, ArrowRight, Package, Box, ShieldCheck, History } from "lucide-react";
import { useCreateGoodsReceipt } from "@/features/purchasing/api/useGoodsReceipts";
import { usePurchaseOrder } from "@/features/purchasing/api/usePurchaseOrders";
import { Breadcrumb } from "@/components/shared/Breadcrumb";
import { PageHeader } from "@/components/shared/PageHeader";
import { Separator } from "@/components/ui/separator";
import { useMasterDataList, useMasterDataItem } from "@/features/master-data/hooks/useMasterDataCRUD";
import { WarehouseSchema, SupplierSchema } from "@/types/master-data";
import { useWarehouseLock } from "@/hooks/useWarehouseLock";

const grnItemSchema = z.object({
 poLineItemId: z.string().min(1, "Required"),
 itemId: z.string().min(1, "Required"),
 itemName: z.string().optional(),
 orderedQuantity: z.number().min(0.01, "Invalid"),
 receivedQuantity: z.number().min(0, "Invalid"),
 lotNumber: z.string().min(1, "Lot number is required"),
 expiryDate: z.string().min(1, "Expiry date is required"),
 notes: z.string().optional(),
});

const formSchema = z.object({
 poId: z.string().min(1, "Reference PO is required"),
 warehouseId: z.string().min(1, "Receiving warehouse is required"),
 supplierId: z.string().min(1, "Supplier is required"),
 items: z.array(grnItemSchema).min(1, "At least one item is required"),
 notes: z.string().optional(),
});

type GRNFormValues = z.infer<typeof formSchema>;

export function GRNForm({ locale }: { locale: 'ar' | 'en' }) {
 const t = useTranslations('procurement.grn');
 const tc = useTranslations('common');
 const router = useRouter();
 const searchParams = useSearchParams();
 const poIdParam = searchParams.get("po");

 const form = useForm<GRNFormValues>({
 resolver: zodResolver(formSchema),
 defaultValues: {
 poId: poIdParam || "",
 warehouseId: "",
 supplierId: "",
 items: [],
 notes: "",
 },
 });

 const selectedWarehouseId = useWatch({
 control: form.control,
 name: "warehouseId",
 });
 const { data: lockState } = useWarehouseLock(selectedWarehouseId || null);
 const isTargetWarehouseLocked = !!lockState?.isLocked;

 const { data: poDetails, isLoading: isPoLoading } = usePurchaseOrder(poIdParam || "");
 const { data: warehouses } = useMasterDataList('warehouses', WarehouseSchema);


 const watchedSupplierId = useWatch({
 control: form.control,
 name: "supplierId",
 });
 const { data: supplier } = useMasterDataItem('suppliers', watchedSupplierId || null, SupplierSchema);

 const { fields, remove } = useFieldArray({
 name: "items",
 control: form.control,
 });

 const createGRN = useCreateGoodsReceipt();

 useEffect(() => {
 if (poDetails) {
 form.setValue("supplierId", poDetails.supplier_id);
 const poItems = poDetails.lines.map((pi) => ({
 poLineItemId: pi.id || `temp- ${Math.random()}`,
 itemId: pi.item.id,
 itemName: locale === 'ar' ? pi.item.name_ar : pi.item.name_en,
 orderedQuantity: pi.quantity,
 receivedQuantity: pi.quantity,
 lotNumber: "",
 expiryDate: "",
 notes: "",
 }));
 form.setValue("items", poItems);
 }
 }, [poDetails, form, locale]);

 const onSubmit = (data: GRNFormValues) => {
 createGRN.mutate(data, {
 onSuccess: () => {
 router.push(`/${locale}/goods-received`);
 },
 });
 };

 return (
 <div className="p-10 max-w-[1600px] mx-auto space-y-12 animate-in fade-in slide-in-from-bottom-6 duration-1000">
 <Breadcrumb 
 items={[
 { label: tc('sidebar.dashboard'), href: `/${locale}` },
 { label: tc('sidebar.grn'), href: `/${locale}/goods-received` },
 { label: t('create_new') }
 ]} 
 />

 <PageHeader
 title={t('title')}
 description={t('new_manifest_sub')}
 actions={
 <div className="flex items-center gap-6">
 <Button 
 variant="outline"
 onClick={() => router.back()}
 className="h-12 px-10 text-label-xs font-semibold uppercase rounded-sm transition-all border-white/5 hover:bg-white/5"
 >
 {tc('cancel')}
 </Button>
 <Button 
 onClick={form.handleSubmit(onSubmit)}
 disabled={createGRN.isPending || isTargetWarehouseLocked || fields.length === 0}
 className="h-12 px-10 bg-cyan-500 hover:bg-cyan-400 text-black text-label-xs font-semibold uppercase rounded-sm transition-all shadow-[0_0_25px_rgba(6,182,212,0.25)] border-none"
 >
 {createGRN.isPending ? tc('saving') : t('save_draft')}
 {!createGRN.isPending && <Save className="ms-2 w-4 h-4" />}
 </Button>
 </div>
 }
 />

 {isTargetWarehouseLocked && (
 <LockBanner message={t('warehouse_locked')} />
 )}

 <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
 <div className="lg:col-span-2 space-y-10">
 <Card className="bg-surface-container-low border-none rounded-sm overflow-hidden shadow-2xl">
 <CardHeader className="pb-8 border-b border-white/5 bg-surface-container-medium/30">
 <div className="flex items-center gap-4">
 <div className="p-3 bg-cyan-500/10 rounded-sm">
 <Receipt className="w-5 h-5 text-cyan-400" />
 </div>
 <div>
 <CardTitle className="text-label-xs font-semibold uppercase text-foreground">{t('document_specification')}</CardTitle>
 <CardDescription className="text-label-xxs font-bold uppercase text-muted-foreground/40">{t('detail_sub')}</CardDescription>
 </div>
 </div>
 </CardHeader>
 <CardContent className="p-10 space-y-10">
 <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
 <div className="flex flex-col gap-3">
 <Label className="text-label-xs font-semibold uppercase text-muted-foreground/40 ps-1">{t('order_reference')}</Label>
 <div className="relative group">
 <Input
 id="poId"
 placeholder={t('scan_placeholder')}
 {...form.register("poId")}
 className="h-14 bg-surface-container-highest/20 border-white/5 font-mono uppercase text-cyan-500 text-label-sm focus:ring-cyan-500/20"
 />
 <Search className="absolute end-4 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground/20 group-focus-within:text-cyan-500 transition-colors" />
 </div>
