            </PermissionGate>
          }
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <MetricCard
          label={tc('total_records')}
          value={stats.total}
          icon={BarcodeIcon}
          color="cyan"
          dir="ltr"
        />

        <MetricCard
          label={tc('status.active')}
          value={stats.active}
          icon={CheckCircle2}
