 <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
 {/* Manager */}
 <div className="space-y-2">
 <Label htmlFor="dept-manager" className="text-label-xs font-semibold uppercase text-muted-foreground/70">{td('fields.manager')}</Label>
                <Input 
                  id="dept-manager" 
                  {...register('manager')} 
