"use client"
// use no memo

import * as React from "react"
import {
 ColumnDef,
 flexRender,
 getCoreRowModel,
 useReactTable,
 getPaginationRowModel,
 getFilteredRowModel,
 SortingState,
 getSortedRowModel,
 ColumnFiltersState,
} from "@tanstack/react-table"

import {
 Table,
 TableBody,
 TableCell,
 TableHead,
 TableHeader,
 TableRow,
} from "@/components/ui/table"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { ChevronLeft, ChevronRight, Download, Search } from "lucide-react"

// A generic translation placeholder mechanism since this is a client component
// and next-intl might not be universally available in simple stories.
// Usually, we'd inject this from the parent via props or use the hook directly.
import { useTranslations } from "next-intl"

interface DataTableProps<TData, TValue> {
 columns: ColumnDef<TData, TValue>[]
 data: TData[]
 searchKey?: string
 searchPlaceholder?: string
 enableExport?: boolean
 onExport?: () => void
}

export function DataTable<TData, TValue>({
 columns,
 data,
 searchKey,
 searchPlaceholder,
 enableExport,
 onExport,
}: DataTableProps<TData, TValue>) {
 const [sorting, setSorting] = React.useState<SortingState>([])
 const [columnFilters, setColumnFilters] = React.useState<ColumnFiltersState>([])
 const t = useTranslations("common");

 const table = useReactTable({
 data,
 columns,
 getCoreRowModel: getCoreRowModel(),
 getPaginationRowModel: getPaginationRowModel(),
 onSortingChange: setSorting,
 getSortedRowModel: getSortedRowModel(),
 onColumnFiltersChange: setColumnFilters,
 getFilteredRowModel: getFilteredRowModel(),
 state: {
 sorting,
 columnFilters,
 },
 })

 const [isRtl, setIsRtl] = React.useState(false)

 React.useEffect(() => {
 setIsRtl(document.documentElement.dir === 'rtl')
 
 const observer = new MutationObserver(() => {
 setIsRtl(document.documentElement.dir === 'rtl')
 })
 observer.observe(document.documentElement, { attributes: true, attributeFilter: ['dir'] })
 return () => observer.disconnect()
 }, [])

 return (
 <div className="space-y-4">
 <div className="flex items-center justify-between">
 {searchKey ? (
 <div className="relative max-w-sm w-full">
 <Search className="absolute start-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
 <Input
 placeholder={searchPlaceholder || t("search") || "Search..."} value={(table.getColumn(searchKey)?.getFilterValue() as string) ?? ""} onChange={(event) =>
 table.getColumn(searchKey)?.setFilterValue(event.target.value)
 }
 className="max-w-sm ps-10"
 />
 </div>
 ) : <div />}
 {enableExport && (
 <Button variant="outline" onClick={onExport} className="bg-surface-container-low hover:bg-surface-container-high border-border-surface">
 <Download className="me-2 h-4 w-4" />
 {t("export") || "Export"}
 </Button>
 )}
 </div>
 <div className="rounded-xl border border-border-surface bg-surface-container-low overflow-hidden shadow-sm">
 <Table>
 <TableHeader>
 {table.getHeaderGroups().map((headerGroup) => (
 <TableRow key={headerGroup.id}>
 {headerGroup.headers.map((header) => {
 return (
 <TableHead key={header.id}>
 {header.isPlaceholder
 ? null
 : flexRender(
 header.column.columnDef.header,
 header.getContext()
 )}
 </TableHead>
 )
 })}
 </TableRow>
 ))}
 </TableHeader>
 <TableBody>
 {table.getRowModel().rows?.length ? (
 table.getRowModel().rows.map((row) => (
 <TableRow
 key={row.id}
 data-state={row.getIsSelected() && "selected"}
 >
 {row.getVisibleCells().map((cell) => (
 <TableCell key={cell.id}>
 {flexRender(cell.column.columnDef.cell, cell.getContext())}
 </TableCell>
 ))}
 </TableRow>
 ))
 ) : (
 <TableRow>
 <TableCell colSpan={columns.length} className="h-24 text-center text-muted-foreground">
 {t("noResults") || "No results."}
 </TableCell>
 </TableRow>
 )}
 </TableBody>
 </Table>
 </div>
 
 <div className="flex items-center justify-end gap-2 py-4">
 <div className="flex-1 text-body-md text-muted-foreground">
 Showing {table.getState().pagination.pageIndex * table.getState().pagination.pageSize + 1} to {Math.min((table.getState().pagination.pageIndex + 1) * table.getState().pagination.pageSize, table.getFilteredRowModel().rows.length)} of {table.getFilteredRowModel().rows.length} entries
 </div>
 <div className="flex items-center gap-2">
 <Button
 variant="outline"
 size="sm"
 onClick={() => table.previousPage()}
 disabled={!table.getCanPreviousPage()}
 className="bg-surface-container-low"
 >
 <ChevronLeft className="h-4 w-4 rtl:rotate-180" />
 <span className="sr-only">Previous</span>
 </Button>
 <Button
 variant="outline"
 size="sm"
 onClick={() => table.nextPage()}
 disabled={!table.getCanNextPage()}
 className="bg-surface-container-low"
 >
 <ChevronRight className="h-4 w-4 rtl:rotate-180" />
 <span className="sr-only">Next</span>
 </Button>
 </div>
 </div>
 </div>
 )
}

"use client";

import React, { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { AlertTriangle, CheckCircle2, PackageSearch, Zap, Calendar, ArrowRight, ShieldAlert, BadgeCheck } from "lucide-react";
import { IssueLot } from "@/features/operations/types";
import { Badge } from "@/components/ui/badge";

// Mock available lots per item ظ¤ sorted by expiry ASC (FEFO rule)
const MOCK_AVAILABLE_LOTS: Record<string, (IssueLot & { availableQty: number })[]> = {
 'item-oil': [{ lotNumber: 'LOT-O01', expiryDate: '2024-11-01', allocatedQuantity: 0, availableQty: 20, isExpired: true },
 { lotNumber: 'LOT-O02', expiryDate: '2025-08-01', allocatedQuantity: 0, availableQty: 50 }],
 'item-salt': [{ lotNumber: 'LOT-S01', expiryDate: '2025-06-01', allocatedQuantity: 0, availableQty: 100 }],
 'item-tomato': [{ lotNumber: 'LOT-T01', expiryDate: '2024-12-31', allocatedQuantity: 0, availableQty: 15 }],
 'item-cheese': [{ lotNumber: 'LOT-C01', expiryDate: '2023-01-01', allocatedQuantity: 0, availableQty: 5, isExpired: true },
 { lotNumber: 'LOT-C02', expiryDate: '2025-09-15', allocatedQuantity: 0, availableQty: 30 }],
};

interface FEFOLotAllocatorProps {
 isOpen: boolean;
 onClose: () => void;
 itemId: string;
 requestedQty: number;
 onAllocate: (lots: IssueLot[]) => void;
}

export function FEFOLotAllocator({ isOpen, onClose, itemId, requestedQty, onAllocate }: FEFOLotAllocatorProps) {
 const availableLots = MOCK_AVAILABLE_LOTS[itemId] ?? [];
 const [allocations, setAllocations] = useState<Record<string, number>>({});

 const { now, nearExpiryThreshold } = React.useMemo(() => {
 const n = new Date();
 const t = new Date(n.getTime() + 30 * 24 * 60 * 60 * 1000);
 return { now: n, nearExpiryThreshold: t };
 }, [isOpen]);

 const totalAllocated = Object.values(allocations).reduce((s, v) => s + v, 0);
 const remaining = requestedQty - totalAllocated;
 const isComplete = Math.abs(remaining) < 0.001;
 const isOver = remaining < -0.001;

 const handleQtyChange = (lotNumber: string, value: string) => {
 const num = Math.max(0, parseFloat(value) || 0);
 setAllocations((prev) => ({ ...prev, [lotNumber]: num }));
 };

 const handleAutoAllocate = () => {
 let left = requestedQty;
 const auto: Record<string, number> = {};
 // FEFO: iterate sorted by expiry ASC (earliest first)
 for (const lot of availableLots) {
 if (lot.isExpired) continue; // Skip expired lots in auto-allocation
 if (left <= 0) break;
 const take = Math.min(lot.availableQty, left);
 auto[lot.lotNumber] = take;
 left -= take;
 }
 setAllocations(auto);
 };

 const handleConfirm = () => {
 const result: IssueLot[] = availableLots
 .filter((l) => (allocations[l.lotNumber] ?? 0) > 0)
 .map((l) => ({
 lotNumber: l.lotNumber,
 expiryDate: l.expiryDate,
 allocatedQuantity: allocations[l.lotNumber] ?? 0,
 isExpired: l.isExpired,
 }));
 onAllocate(result);
 onClose();
 };

 return (
 <Dialog open={isOpen} onOpenChange={onClose}>
 <DialogContent className="sm:max-w-2xl bg-surface-container-lowest border-none p-0 overflow-hidden rounded-3xl">
 <div className="bg-muted/10 p-8 border-b border-border-surface">
 <DialogHeader>
 <div className="flex items-center gap-4 mb-2">
 <div className="p-3 rounded-2xl bg-operational-cyan/10 text-operational-cyan border border-operational-cyan/20">
 <PackageSearch className="w-6 h-6" />
 </div>
 <div>
 <DialogTitle className="text-title-lg font-semibold text-foreground">
 FEFO Lot Allocation
 </DialogTitle>
 <p className="text-label-xs font-semibold text-muted-foreground/40 uppercase mt-0.5">
 Fulfillment Protocol for <span className="text-operational-cyan font-mono">{itemId}</span>
 </p>
 </div>
 <Badge className="ms-auto bg-muted border-none text-label-xs font-semibold uppercase px-3 h-8 rounded-lg">
 SAR-882 System
 </Badge>
 </div>
 </DialogHeader>
 </div>

 <div className="p-8 space-y-8">
 {/* Allocation Progress Bar */}
 <div className="bg-muted/5 p-6 rounded-3xl">
 <div className="flex items-center justify-between mb-4">
 <div className="flex flex-col">
 <span className="text-label-xs font-semibold uppercase text-muted-foreground/40">Required Commitment</span>
 <span className="text-headline-lg font-semibold tabular-nums">{requestedQty} <span className="text-label-sm text-muted-foreground/30">Units</span></span>
 </div>
 <div className="flex flex-col items-end">
 <span className="text-label-xs font-semibold uppercase text-muted-foreground/40">Allocated Status</span>
 <div className="flex items-center gap-2">
 <span className={`text-headline-lg font-semibold tabular-nums ${isComplete ? 'text-status-success' : isOver ? 'text-status-error' : 'text-status-warning'}`}>
 {totalAllocated}
 </span>
 {isComplete ? <BadgeCheck className="w-5 h-5 text-status-success" /> : null}
 </div>
 </div>
 </div>
 
 <div className="h-3 bg-muted/20 rounded-full overflow-hidden border border-black/5 p-0.5">
 <div 
 className={`h-full rounded-full transition-all duration-700 ${isComplete ? 'bg-status-success' : isOver ? 'bg-status-error' : 'bg-primary animate-pulse'}`}
 style={{ width: `${Math.min(100, (totalAllocated / requestedQty) * 100)}%` }}
 />
 </div>
 
 <div className="flex items-center justify-between mt-4">
 <p className="text-label-xs font-bold text-muted-foreground/40 italic">
 {isComplete ? "Allocation parameters satisfied." : isOver ? "Warning: Over-allocation detected." : "Awaiting full allocation sequence..."}
 </p>
 <Button 
 size="sm" 
 variant="outline" 
 onClick={handleAutoAllocate} 
 className="h-9 px-4 border-primary/30 text-primary bg-primary/5 hover:bg-primary hover:text-primary-foreground rounded-xl text-label-xxs font-semibold uppercase transition-all"
 >
 <Zap className="w-3 h-3 me-2" />
 FEFO Smart Allocate
 </Button>
 </div>
 </div>

 {/* Lot Selection List */}
 <div className="space-y-4">
 <h4 className="text-label-xs font-semibold uppercase text-muted-foreground/60 px-2 flex items-center gap-2">
 <Calendar className="w-3 h-3" />
 Available Batches (Sorted by Expiry)
 </h4>
 
 {availableLots.length === 0 ? (
 <div className="py-12 text-center bg-muted/5 rounded-3xl border border-dashed border-border-surface">
 <PackageSearch className="w-12 h-12 mx-auto text-muted-foreground/10 mb-4" />
 <p className="text-label-xs font-bold text-muted-foreground/30 uppercase">No available lots in inventory</p>
 </div>
 ) : (
 <div className="grid grid-cols-1 gap-3 max-h-[400px] overflow-y-auto pe-2 custom-scrollbar">
 {availableLots.map((lot) => {
 const lotExpiryDate = new Date(lot.expiryDate);
 const isExpired = lot.isExpired || lotExpiryDate < now;
 const isNearExpiry = !isExpired && lotExpiryDate < nearExpiryThreshold;
 
 return (
 <div
 key={lot.lotNumber}
 className={`p-5 rounded-2xl border transition-all duration-300 group ${ isExpired ? 'bg-status-error/5 border-status-error/20 opacity-60' : isNearExpiry ? 'bg-status-warning/5 border-status-warning/20 hover:bg-status-warning/10' : 'bg-surface-container-low border-border-surface hover:border-operational-cyan/30 hover:bg-muted/50' }`}
 >
 <div className="flex items-center gap-6">
 <div className="flex-1 space-y-1">
 <div className="flex items-center gap-3">
 <span className="text-body-md font-semibold text-foreground">{lot.lotNumber}</span>
 {isExpired ? (
 <Badge variant="destructive" className="h-5 px-2 rounded-md text-label-xxs font-semibold uppercase bg-status-error/10 text-status-error border-none">
 <ShieldAlert className="w-2.5 h-2.5 me-1" />
 Protocol Violation (Expired)
 </Badge>
 ) : isNearExpiry ? (
 <Badge className="h-5 px-2 rounded-md text-label-xxs font-semibold uppercase bg-status-warning/10 text-status-warning border-none">
 Urgent Rotation
 </Badge>
 ) : (
 <Badge className="h-5 px-2 rounded-md text-label-xxs font-semibold uppercase bg-status-success/10 text-status-success border-none">
 Optimal Batch
 </Badge>
 )}
 </div>
 <div className="flex items-center gap-4 text-label-xs font-bold text-muted-foreground/40 uppercase" dir="ltr">
 <span className="flex items-center gap-1.5">
 <Calendar className="w-3 h-3" />
 Exp: <span className={isExpired ? "text-status-error" : "text-foreground/60"}>{lot.expiryDate}</span>
 </span>
 <span className="w-1 h-1 rounded-full bg-muted/20" />
 <span>In Stock: <span className="text-foreground/60">{lot.availableQty}</span></span>
 </div>
 </div>
 
 <div className="flex flex-col items-end gap-1.5">
 <Label className="text-label-xxs font-semibold uppercase text-muted-foreground/40">Issuing Qty</Label>
 <div className="relative">
 <Input
 type="number"
 min="0"
 max={lot.availableQty}
 step="0.01"
 className="w-32 h-10 text-center font-mono font-semibold text-label-xs"
 dir="ltr"
 disabled={isExpired}
 value={allocations[lot.lotNumber] ?? ''} onChange={(e) => handleQtyChange(lot.lotNumber, e.target.value)}
 />
 <div className="absolute end-3 top-1/2 -translate-y-1/2 text-label-xxs font-semibold text-muted-foreground/20 uppercase pointer-events-none">UNIT</div>
 </div>
 </div>
 </div>
 </div>
 );
 })}
 </div>
 )}
 </div>
 </div>

 <div className="p-8 bg-muted/10 border-t border-border-surface flex flex-col md:flex-row items-center justify-between gap-4">
 <Button 
 variant="ghost" 
 onClick={onClose}
 className="text-label-xs font-semibold uppercase text-muted-foreground/40 hover:text-foreground h-12 px-8 rounded-xl"
 >
 Cancel Allocation
 </Button>
 
 <Button
 className="h-12 px-10 bg-primary hover:bg-primary/90 text-primary-foreground text-label-xs font-semibold uppercase rounded-xl transition-all disabled:opacity-30 disabled:grayscale active:scale-95"
 disabled={!isComplete}
 onClick={handleConfirm}
 >
 <CheckCircle2 className="me-2 w-3.5 h-3.5" />
 Synchronize Fulfillment
 <ArrowRight className="ms-2 w-3.5 h-3.5 opacity-40" />
 </Button>
 </div>
 </DialogContent>
 </Dialog>
 );
}

import React, { ReactNode, ElementType, isValidElement } from 'react';
import { Card, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { cn } from '@/lib/utils';

interface MetricCardProps {
 label: string;
 value: string | number;
 trend?: string | ReactNode;
 icon?: ElementType | ReactNode;
 color?: 'cyan' | 'emerald' | 'amber' | 'rose' | 'indigo';
 className?: string;
 dir?: 'ltr' | 'rtl';
}

const colorMap = {
 cyan: {
 text: 'text-status-success',
 glow: 'from-status-success/50',
 bg: 'bg-status-success/10',
 },
 emerald: {
 text: 'text-status-success',
 glow: 'from-status-success/50',
 bg: 'bg-status-success/10',
 },
 amber: {
 text: 'text-status-warning',
 glow: 'from-status-warning/50',
 bg: 'bg-status-warning/10',
 },
 rose: {
