 </span>
 </div>
 </div>
 );
 })}
 </div>

 {/* Step Content */}
 <div className="mt-4 bg-surface-container-lowest/50 rounded-2xl p-8 border border-white/5 shadow-xl relative overflow-hidden min-h-[400px]">
