 {wizard.step === 'VALIDATING' && <StepValidate wizard={wizard} locale={locale} />}
 {wizard.step === 'ERRORS' && <StepErrors wizard={wizard} locale={locale} />}
 {(wizard.step === 'COMMIT' || wizard.step === 'SUCCESS') && <StepCommit wizard={wizard} locale={locale} />}
 </div>
 </div>
 </div>
 );
}

