'use client';

import { useState, useRef } from 'react';
import { useTranslations } from 'next-intl';
import { Download, Upload, FileIcon, X, Loader2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { getTemplateHeaders } from '@/lib/import/templates';
import * as XLSX from 'xlsx';
import { cn } from '@/lib/utils';

import { WizardReturn } from '../../hooks/useImportWizard';

interface StepUploadProps {
 wizard: WizardReturn;
 locale: string;
}

export function StepUpload({ wizard, locale }: StepUploadProps) {
 const t = useTranslations('master_data.import');
 const [file, setFile] = useState<File | null>(null);
 const [isParsing, setIsParsing] = useState(false);
 const fileInputRef = useRef<HTMLInputElement>(null);

 const handleDownloadTemplate = () => {
 const headers = getTemplateHeaders(wizard.entity);
 const ws = XLSX.utils.aoa_to_sheet([headers]);
 const wb = XLSX.utils.book_new();
 XLSX.utils.book_append_sheet(wb, ws, 'Template');
 XLSX.writeFile(wb, `${wizard.entity}_template.xlsx`);
 };

 const onFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
 const selectedFile = e.target.files?.[0];
 if (!selectedFile) return;

 // Check file type
 if (!selectedFile.name.endsWith('.xlsx')) {
 alert(t('invalid_file_type')); // In real app use a toast
 return;
 }

 // Check size (20MB)
 if (selectedFile.size > 20 * 1024 * 1024) {
 alert(t('file_too_large'));
 return;
 }

 setFile(selectedFile);
 };

 const handleUpload = () => {
 if (!file) return;

 setIsParsing(true);
 const reader = new FileReader();
 reader.onload = (e) => {
 try {
 const data = new Uint8Array(e.target?.result as ArrayBuffer);
 const workbook = XLSX.read(data, { type: 'array' });
 const sheet = workbook.Sheets[workbook.SheetNames[0]];
 const json = XLSX.utils.sheet_to_json(sheet);
 
 if (json.length === 0) {
 alert(t('empty_file'));
 setIsParsing(false);
 return;
 }

 wizard.setFileData(file.name, file.size, json as Record<string, unknown>[]);
 } catch (error) {
 console.error('Error parsing file:', error);
 alert(t('parse_error'));
 } finally {
 setIsParsing(false);
 }
 };
 reader.readAsArrayBuffer(file);
 };

 return (
 <div className="flex flex-col items-center justify-center gap-10 py-10 animate-in fade-in slide-in-from-bottom-4 duration-500">
 <div className="text-center space-y-4 max-w-xl">
 <h2 className="text-headline-lg font-semibold uppercase text-foreground">
 {t('upload_title')}
 </h2>
 <p className="text-muted-foreground text-body-md leading-relaxed">
 {t('upload_description')}
 </p>
 </div>

 <div className="w-full max-w-2xl space-y-8">
 {/* Drop Zone / Selection */}
 {!file ? (
 <div 
 onClick={() => fileInputRef.current?.click()}
 className="group cursor-pointer border-2 border-dashed border-muted-foreground/10 rounded-3xl p-16 flex flex-col items-center gap-6 transition-all hover:border-cyan-500/30 hover:bg-cyan-500/[0.02]"
 >
 <div className="w-20 h-20 rounded-2xl bg-surface-container-low flex items-center justify-center transition-all group-hover:scale-110 group-hover:bg-cyan-500/10 group-hover:text-cyan-500">
 <Upload className="w-10 h-10" />
 </div>
 <div className="text-center">
 <p className="font-bold uppercase text-body-md mb-1">{t('click_to_upload')}</p>
 <p className="text-label-sm text-muted-foreground font-medium uppercase opacity-60">XLSX ONLY ظت MAX 20MB</p>
 </div>
 <input 
 type="file" 
 ref={fileInputRef} 
 className="hidden" 
 accept=".xlsx"
 onChange={onFileChange}
 />
 </div>
 ) : (
 <div className="bg-surface-container-low/50 rounded-3xl p-8 border border-white/5 flex items-center justify-between animate-in zoom-in-95 duration-300">
 <div className="flex items-center gap-5">
 <div className="w-16 h-16 rounded-xl bg-cyan-500/10 text-cyan-500 flex items-center justify-center">
 <FileIcon className="w-8 h-8" />
 </div>
 <div>
 <p className="font-bold text-title-sm leading-none mb-2">{file.name}</p>
 <p className="text-label-sm font-mono text-muted-foreground uppercase">
 {(file.size / 1024 / 1024).toFixed(2)} MB
