'use client';
import { z } from 'zod';
import { useQuery } from '@tanstack/react-query';
import { apiClient } from '@/lib/api/client';


import { AdjustmentStatus, ALL_STATUSES } from '@/contracts/statuses';

export const AdjustmentStatusSchema = z.enum(ALL_STATUSES);


export const AdjustmentLineSchema = z.object({
 id: z.string(),
 item: z.object({
 id: z.string(),
 code: z.string(),
 name_ar: z.string(),
 name_en: z.string(),
 primary_uom: z.object({
 id: z.string(),
 code: z.string(),
 }),
 }),
 direction: z.enum(['INCREASE', 'DECREASE']),
 qty_before: z.number(),
 qty_adjusted: z.number(),
 uom_id: z.string(),
 reason_notes: z.string().optional(),
});

export const AdjustmentDetailSchema = z.object({
 id: z.string(),
 document_number: z.string(),
 status: AdjustmentStatusSchema,
 warehouse_id: z.string(),
 reason: z.string(),
 notes: z.string().nullable().optional(),
 reject: z.string().nullable().optional(),
 movement_id: z.string().nullable().optional(),
 approved_by: z.string().nullable().optional(),
 posted_at: z.string().nullable().optional(),
 created_at: z.string().optional(),
 version: z.number().optional(),
 lines: z.array(AdjustmentLineSchema),
 timeline: z.array(z.object({
 status: z.string(),
 at: z.string(),
 by: z.string(),
 })).optional(),
});


export type AdjustmentDetail = z.infer<typeof AdjustmentDetailSchema>;
export type AdjustmentLine = z.infer<typeof AdjustmentLineSchema>;

export function useAdjustment(id: string | null) {
 return useQuery({
 queryKey: ['adjustment', id],
 queryFn: () => apiClient.get(`/operations/adjustments/${id}`, AdjustmentDetailSchema),
 enabled: !!id,
 staleTime: 60_000,
 });
}

'use client';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useSafeMutation } from '@/core/concurrency/useSafeMutation';
import { apiClient } from '@/lib/api/client';
import { successSchema } from '@/types/api';

import { ADJUSTMENT_STATUS } from '@/contracts/statuses';
import { AdjustmentDetail } from './useAdjustment';

export function useApproveAdjustment(id: string, options?: { onConflict?: () => void }) {
  const queryClient = useQueryClient();
  return useSafeMutation({
    onConflict: options?.onConflict,
    mutationFn: (version: number) =>
      apiClient.post(`/operations/adjustments/${id}/approve`, successSchema, { version }),
    onSuccess: () => {
      queryClient.setQueryData(['adjustment', id], (old: AdjustmentDetail | undefined) => {
        if (!old) return old;
        return {
          ...old,
          status: ADJUSTMENT_STATUS.APPROVED,
          approved_by: 'Current User',
          timeline: [
            ...(old.timeline || []),
            { status: ADJUSTMENT_STATUS.APPROVED, at: new Date().toISOString(), by: 'Current User' }
          ]
        };
      });
      queryClient.invalidateQueries({ queryKey: ['adjustments'] });
    },
    onError: (error) => {
      console.error('Failed to approve adjustment:', error);
    }
  });
}

