 return useSafeMutation({
 onConflict: options?.onConflict,
 mutationFn: (data: CreateKitchenRequestDTO & { isDraft?: boolean }) => 
 apiClient.post('/operations/kitchen-requests', KitchenRequestDetailSchema, data),
