});

export const StocktakeSessionSchema = z.object({
  id: z.string(),
  session_number: z.string(),
  session_name: z.string(),
  warehouse_id: z.string(),
  warehouse_name: z.string().optional(),
  status: z.enum(ALL_DOCUMENT_STATUSES),
  snapshot_at: z.string(),
  started_by: z.string(),
