/**
 * API Adapters
 * Utilities to normalize backend snake_case data into frontend camelCase structures.
 */

import { 
  PurchaseRequest, 
  PurchaseOrder, 
  GRN, 
  Transfer, 
  StockIssue, 
  Adjustment,
  BaseDocument
} from '@/types/documents';

/**
 * Recursive function to convert snake_case keys to camelCase
 */
export function toCamelCase<T>(obj: any): T {
  if (Array.isArray(obj)) {
    return obj.map(v => toCamelCase(v)) as any;
  }
  if (obj !== null && typeof obj === 'object' && !(obj instanceof Date)) {
    return Object.keys(obj).reduce((acc, key) => {
      const camelKey = key.replace(/_([a-z])/g, (_, letter) => letter.toUpperCase());
      acc[camelKey] = toCamelCase(obj[key]);
      return acc;
    }, {} as any);
  }
  return obj;
}

/**
 * Recursive function to convert camelCase keys to snake_case
 */
export function toSnakeCase<T>(obj: any): T {
  if (Array.isArray(obj)) {
    return obj.map(v => toSnakeCase(v)) as any;
  }
  if (obj !== null && typeof obj === 'object' && !(obj instanceof Date)) {
    return Object.keys(obj).reduce((acc, key) => {
      const snakeKey = key.replace(/[A-Z]/g, letter => `_${letter.toLowerCase()}`);
      acc[snakeKey] = toSnakeCase(obj[key]);
      return acc;
    }, {} as any);
  }
  return obj;
}

/**
 * Domain-specific normalization helpers
 * While toCamelCase handles generic keys, these functions can handle 
 * complex mappings or value transformations if needed.
 */

export const normalizeDocument = <T extends BaseDocument>(data: any): T => {
  return toCamelCase<T>(data);
};

export const normalizePR = (data: any): PurchaseRequest => normalizeDocument<PurchaseRequest>(data);
export const normalizePO = (data: any): PurchaseOrder => normalizeDocument<PurchaseOrder>(data);
export const normalizeGRN = (data: any): GRN => normalizeDocument<GRN>(data);
export const normalizeTransfer = (data: any): Transfer => normalizeDocument<Transfer>(data);
export const normalizeIssue = (data: any): StockIssue => normalizeDocument<StockIssue>(data);
export const normalizeAdjustment = (data: any): Adjustment => normalizeDocument<Adjustment>(data);

import { ZodSchema } from 'zod';
import type { ApiError } from '@/types/api';
import { ConflictError } from './ConflictError';

const BASE = process.env.NEXT_PUBLIC_API_URL ?? 'http://localhost:3001/api/v1';

async function request<T>(method: string, path: string, schema: ZodSchema<T>, body?: unknown): Promise<T> {
 const token = typeof window !== 'undefined' ? localStorage.getItem('logirest_token') : null;
 const locale = typeof document !== 'undefined' ? document.documentElement.lang : 'ar';
 
  if (process.env.NEXT_PUBLIC_USE_MOCKS === 'true') {
    const { getMockResponse } = await import('./mocks/index');
    const mockData = await getMockResponse(method, path, body);
    if (mockData !== undefined) {
      // Detect mock error responses and throw them as API errors
      if (mockData && typeof mockData === 'object' && 'error' in (mockData as any)) {
        const error = (mockData as any).error;
        // Handle mock 409 or version conflicts
        if (error.status === 409 || error.code === 'VERSION_CONFLICT') {
          throw new ConflictError({
            message: error.message || 'Conflict detected',
            code: error.code || 'VERSION_CONFLICT',
            currentVersion: error.current_version,
            updatedBy: error.updated_by,
            updatedAt: error.updated_at,
          });
        }
        throw error;
      }
      return schema.parse(mockData);
    }
  }

 const res = await fetch(`${BASE}${path}`, {
 method,
 headers: {
 'Content-Type': 'application/json',
 'Accept-Language': locale,
 ...(token ? { Authorization: `Bearer ${token}` } : {}),
 },
 body: body ? JSON.stringify(body) : undefined,
 });
 
  if (res.status === 409) {
    const data = await res.json().catch(() => ({}));
    throw new ConflictError({
      message: data.message || 'Conflict detected',
      code: data.code || 'VERSION_CONFLICT',
      currentVersion: data.current_version,
      updatedBy: data.updated_by,
      updatedAt: data.updated_at,
    });
  }

  if (!res.ok) {
    const err: ApiError = await res.json().catch(() => ({ code: 'NETWORK_ERROR', message: 'errors.network', field_errors: null }));
    throw err;
  }
 
 const data = await res.json();
 return schema.parse(data);
}

export const apiClient = {
 get: <T>(path: string, schema: ZodSchema<T>) => request<T>('GET', path, schema),
 post: <T>(path: string, schema: ZodSchema<T>, body?: unknown) => request<T>('POST', path, schema, body),
 put: <T>(path: string, schema: ZodSchema<T>, body?: unknown) => request<T>('PUT', path, schema, body),
 del: <T>(path: string, schema: ZodSchema<T>) => request<T>('DELETE', path, schema),
};

import { ConflictError } from './ConflictError';
import { Mutation } from '@tanstack/react-query';

export interface ConflictEventPayload {
  error: ConflictError;
  mutation: Mutation<any, any, any, any>;
  variables: any;
}

type ConflictListener = (payload: ConflictEventPayload) => void;

class ConflictBus {
  private listeners: ConflictListener[] = [];

  subscribe(listener: ConflictListener) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter((l) => l !== listener);
    };
  }

  emit(payload: ConflictEventPayload) {
    this.listeners.forEach((l) => l(payload));
  }
}

export const conflictBus = new ConflictBus();

import { getMockResponse as getAdapterResponse } from '@/infrastructure/mock/mock-api.adapter';
import { inventoryMocks } from './inventory';
import { notificationsMocks } from './notifications';
import { adminMocks } from './admin';
import { authMocks } from './auth';
import { reportsMocks } from './reports';

type MockDb = Record<string, unknown>;
const db: MockDb = { 
  ...inventoryMocks, 
  ...notificationsMocks, 
  ...adminMocks,
  ...authMocks,
  ...reportsMocks
};

export async function getMockResponse(method: string, path: string, body?: any): Promise<unknown> {
  // 1. Try new Repository-based Mock Adapter first
  const adapterResponse = await getAdapterResponse(method, path, body);
  if (adapterResponse !== undefined) return adapterResponse;

  // 2. Fallback to legacy static mocks
  const normalizedPath = path.split('?')[0];
  const key = `${method.toUpperCase()} ${normalizedPath}`;

  // Try exact match
  if (db[key]) {
    const mock = db[key];
    return typeof mock === 'function' ? mock(body, normalizedPath) : mock;
  }

  // Try pattern matching
  for (const dbKey in db) {
    if (dbKey.includes(':')) {
      const pattern = dbKey.replace(/:[a-zA-Z]+/g, '[^/]+');
      const regex = new RegExp(`^${pattern}$`);
      if (regex.test(key)) {
        const mock = db[dbKey];
        return typeof mock === 'function' ? mock(body, normalizedPath) : mock;
      }
    }
  }

  return undefined;
}

