import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { useUnsavedChanges } from './UnsavedChangesProvider';

interface UnsavedChangesDialogProps {
  open: boolean;
  onClose: () => void;
  pendingNavigation: { href: string; options?: any } | null;
}

export const UnsavedChangesDialog: React.FC<UnsavedChangesDialogProps> = ({
  open,
  onClose,
  pendingNavigation,
}) => {
  const t = useTranslations('common.unsavedChanges');
  const { confirmNavigation } = useUnsavedChanges();
  const router = useRouter();

  const handleLeave = () => {
    if (!pendingNavigation) {
      confirmNavigation();
      return;
    }

    if (pendingNavigation.href === 'BACK') {
      confirmNavigation();
      window.history.back();
    } else {
      confirmNavigation();
      router.push(pendingNavigation.href, pendingNavigation.options);
    }
  };

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="sm:max-w-[425px]">
        <DialogHeader>
          <DialogTitle>{t('title')}</DialogTitle>
          <DialogDescription>{t('description')}</DialogDescription>
        </DialogHeader>
        <DialogFooter className="gap-2 sm:gap-0">
          <Button variant="secondary" onClick={onClose}>
            {t('stay')}
          </Button>
          <Button variant="destructive" onClick={handleLeave}>
            {t('leave')}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

'use client';

import React, { createContext, useContext, useState, useCallback, useEffect } from 'react';
import { UnsavedChangesDialog } from './UnsavedChangesDialog';
import { locales } from '@/i18n/routing';

interface PendingNavigation {
  href: string;
  options?: any;
}

interface UnsavedChangesContextType {
  isDirty: boolean;
  registerDirty: (dirty: boolean) => void;
  confirmNavigation: () => void;
  openDialog: (targetPath: string, options?: any) => void;
}

const UnsavedChangesContext = createContext<UnsavedChangesContextType | undefined>(undefined);

/**
 * UnsavedChangesProvider
 * 
 * Provides a global mechanism to prevent data loss by intercepting navigation
 * when there are unsaved changes (isDirty).
 * 
 * Intercepts:
 * 1. Browser refresh/close (beforeunload)
 * 2. Browser back/forward buttons (popstate)
 * 3. Link clicks (standard <a> tags)
 * 4. Programmatic navigation (via useUnsavedChangesGuard)
 */
export const UnsavedChangesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isDirty, setIsDirty] = useState(false);
  const [pendingNavigation, setPendingNavigation] = useState<PendingNavigation | null>(null);
  const [open, setOpen] = useState(false);

  const registerDirty = useCallback((dirty: boolean) => {
    setIsDirty(dirty);
  }, []);

  const openDialog = useCallback((targetPath: string, options?: any) => {
    setPendingNavigation({ href: targetPath, options });
    setOpen(true);
  }, []);

  const confirmNavigation = useCallback(() => {
    setIsDirty(false);
    setOpen(false);
    setPendingNavigation(null);
  }, []);

  const closeDialog = useCallback(() => {
    setOpen(false);
    setPendingNavigation(null);
  }, []);

  // Handle browser close/refresh (Native browser dialog)
  useEffect(() => {
    const handleBeforeUnload = (e: BeforeUnloadEvent) => {
      if (isDirty) {
        e.preventDefault();
        e.returnValue = ''; // Standard trigger for browser confirmation
      }
    };

    window.addEventListener('beforeunload', handleBeforeUnload);
    return () => window.removeEventListener('beforeunload', handleBeforeUnload);
  }, [isDirty]);

  // Handle popstate (browser back/forward)
  useEffect(() => {
    const handlePopState = () => {
      if (isDirty) {
        // Prevent immediate navigation by pushing the state back
        window.history.pushState(null, '', window.location.href);
        openDialog('BACK');
      }
    };

    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, [isDirty, openDialog]);

  // Intercept standard link clicks
  useEffect(() => {
    const handleClick = (e: MouseEvent) => {
      if (!isDirty) return;

      const target = e.target as HTMLElement;
      const anchor = target.closest('a');

      // Intercept only internal links without skip-guard attribute
      if (
        anchor && 
        anchor.href && 
        !anchor.target && 
        !anchor.hasAttribute('download') &&
        anchor.getAttribute('data-skip-guard') !== 'true'
      ) {
        const url = new URL(anchor.href);

        // Ensure it's the same origin
        if (url.origin === window.location.origin) {
          const targetPath = url.pathname + url.search + url.hash;
          const currentPath = window.location.pathname + window.location.search + window.location.hash;

          if (targetPath !== currentPath) {
            e.preventDefault();

            // Strip locale prefix if present to avoid double-locale in localized router
            let unlocalizedPath = targetPath;
            const segments = targetPath.split('/');
            if (segments.length > 1 && locales.includes(segments[1] as any)) {
              unlocalizedPath = '/' + segments.slice(2).join('/');
              // Preserve search and hash which were already part of targetPath
            }

            openDialog(unlocalizedPath);
          }
        }
      }
    };

    window.addEventListener('click', handleClick, true);
    return () => window.removeEventListener('click', handleClick, true);
  }, [isDirty, openDialog]);

  return (
    <UnsavedChangesContext.Provider value={{ isDirty, registerDirty, confirmNavigation, openDialog }}>
      {children}
      <UnsavedChangesDialog
        open={open}
        onClose={closeDialog}
        pendingNavigation={pendingNavigation}
      />
    </UnsavedChangesContext.Provider>
  );
};

export const useUnsavedChanges = () => {
  const context = useContext(UnsavedChangesContext);
  if (!context) {
    throw new Error('useUnsavedChanges must be used within an UnsavedChangesProvider');
  }
  return context;
};

'use client';

import { useEffect, useCallback, useMemo } from 'react';
import { useUnsavedChanges } from './UnsavedChangesProvider';
import { useRouter as useNextIntlRouter } from '@/i18n/navigation';

export interface GuardedRouterOptions {
  skipGuard?: boolean;
  [key: string]: any;
}

/**
 * useUnsavedChangesGuard
 * 
 * A hook for components (usually forms) to register their dirty state
 * and get a guarded router that intercepts navigation attempts.
 * 
 * @param componentDirty Optional boolean to automatically sync with global dirty state
 */
export const useUnsavedChangesGuard = (componentDirty?: boolean) => {
  const { isDirty: globalDirty, registerDirty, openDialog } = useUnsavedChanges();
  const baseRouter = useNextIntlRouter();

  // Automatically sync component-level dirty state with global state
  useEffect(() => {
    if (componentDirty !== undefined) {
      registerDirty(componentDirty);
    }

    // Cleanup: reset dirty state on unmount
    return () => {
      if (componentDirty !== undefined) {
        registerDirty(false);
      }
    };
  }, [componentDirty, registerDirty]);

  const setDirty = useCallback((dirty: boolean) => {
    registerDirty(dirty);
  }, [registerDirty]);

  /**
   * Guarded Router
   * Intercepts push, replace, and back calls to show the unsaved changes dialog
   * if the application is in a dirty state.
   */
  const guardedRouter = useMemo(() => ({
    ...baseRouter,
    push: (href: string, options?: GuardedRouterOptions) => {
      if (globalDirty && !options?.skipGuard) {
        openDialog(href, options);
      } else {
        // If skipGuard is true, we should also reset the dirty state
        if (options?.skipGuard) {
          registerDirty(false);
        }
        baseRouter.push(href, options as any);
      }
    },
    replace: (href: string, options?: GuardedRouterOptions) => {
      if (globalDirty && !options?.skipGuard) {
        openDialog(href, options);
      } else {
        if (options?.skipGuard) {
          registerDirty(false);
        }
        baseRouter.replace(href, options as any);
      }
    },
    back: () => {
      if (globalDirty) {
        openDialog('BACK');
      } else {
        baseRouter.back();
      }
    }
  }), [baseRouter, globalDirty, openDialog, registerDirty]);

  return {
    isDirty: globalDirty,
    setDirty,
    registerDirty,
    router: guardedRouter
  };
};

'use client';

import React, { useEffect, useState, useCallback } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { conflictBus, ConflictEventPayload } from '@/lib/api/conflict-bus';
import { ConflictDialog } from '@/components/shared/ConflictDialog';
import { useUnsavedChanges } from '@/lib/unsaved-changes/UnsavedChangesProvider';

export function ConflictProvider({ children }: { children: React.ReactNode }) {
  const [payload, setPayload] = useState<ConflictEventPayload | null>(null);
  const [retryCount, setRetryCount] = useState(0);
  const [isRetrying, setIsRetrying] = useState(false);
  const queryClient = useQueryClient();
  const { registerDirty } = useUnsavedChanges();

  useEffect(() => {
    return conflictBus.subscribe((newPayload) => {
      // Prevent dialog stacking: ignore new conflicts if one is already being handled
      setPayload((prev) => prev || newPayload);
    });
  }, []);

  const handleClose = useCallback(() => {
    setPayload(null);
    setRetryCount(0);
    setIsRetrying(false);
  }, []);

  const handleReload = useCallback(() => {
    // 1. Clear dirty state to allow fresh data loading without guard interference
    registerDirty(false);

    // 2. Targeted Invalidation: Try to refresh only the affected resource domain
    const mutationKey = payload?.mutation?.options?.mutationKey as any[];
    if (Array.isArray(mutationKey) && mutationKey.length > 0) {
      queryClient.invalidateQueries({ queryKey: [mutationKey[0]] });
    } else {
      queryClient.invalidateQueries();
    }

    handleClose();
  }, [queryClient, handleClose, payload, registerDirty]);

  const handleRetry = useCallback(async () => {
    if (!payload || retryCount >= 1) return;

    setIsRetrying(true);
    try {
      // Step A: Sync local query state with server before retry
      const mutationKey = payload.mutation?.options?.mutationKey as any[];
      if (Array.isArray(mutationKey) && mutationKey.length > 0) {
        await queryClient.refetchQueries({ queryKey: [mutationKey[0]] });
      }

      // Step B: Update version in variables
      const latestVersion = payload.error.currentVersion;
      const updatedVariables = { 
        ...(typeof payload.variables === 'object' ? payload.variables : { id: payload.variables }) 
      };

      if ('version' in updatedVariables) {
        updatedVariables.version = latestVersion;
      }

      // Step C: Re-execute using the stable mutation function
      const mutationFn = (payload.mutation.options as any).mutationFn;
      if (typeof mutationFn === 'function') {
        await mutationFn(updatedVariables);

        // Success - Final cleanup and sync
        if (Array.isArray(mutationKey) && mutationKey.length > 0) {
          queryClient.invalidateQueries({ queryKey: [mutationKey[0]] });
        }
        handleClose();
      } else {
        handleReload();
      }
    } catch (err) {
      // If it fails again (even if another 409), increment retryCount to force manual reload
      setRetryCount((prev) => prev + 1);
    } finally {
      setIsRetrying(false);
    }
  }, [payload, retryCount, queryClient, handleClose, handleReload]);

  return (
    <>
      {children}
      <ConflictDialog
        open={!!payload}
        error={payload?.error || null}
        onRetry={handleRetry}
        onReload={handleReload}
        onClose={handleClose}
        isRetrying={isRetrying}
        retryCount={retryCount}
      />
    </>
  );
}

'use client';
import { QueryClient, QueryClientProvider, MutationCache } from '@tanstack/react-query';
import { useState } from 'react';
import { ConflictError } from '@/lib/api/ConflictError';
import { conflictBus } from '@/lib/api/conflict-bus';

export function QueryProvider({ children }: { children: React.ReactNode }) {
  const [client] = useState(() => new QueryClient({
    mutationCache: new MutationCache({
      onError: (error, variables, _context, mutation) => {
        if (error instanceof ConflictError) {
          // Attach original version from variables for UX comparison
          if (variables && typeof variables === 'object' && 'version' in variables) {
            (error as any).originalVersion = (variables as any).version;
          }
          conflictBus.emit({ error, mutation, variables });
        }
      },
    }),
    defaultOptions: { 
      queries: { 
        staleTime: 60_000, 
        gcTime: 5 * 60_000, 
        retry: 1 
      } 
    },
  }));

  return <QueryClientProvider client={client}>{children}</QueryClientProvider>;
}

